// The preview: the site renders the draft with its own pipeline, and Carrel serves that page into a
// sandboxed iframe. The page is the site's markup, so it runs with no script, no forms, no network
// but the site's own styles and images, and an opaque origin that cannot reach Carrel.

/** The policy for a preview document. `sandbox` in the header holds even if the iframe attribute is lost. */
export function previewPolicy(siteOrigin: string): string {
  return [
    "sandbox",
    "default-src 'none'",
    `style-src ${siteOrigin} 'unsafe-inline'`,
    `img-src ${siteOrigin} data:`,
    `font-src ${siteOrigin}`,
    `media-src ${siteOrigin}`,
    "script-src 'none'",
    "form-action 'none'",
    `base-uri ${siteOrigin}`,
    "frame-ancestors 'self'",
  ].join("; ");
}

/**
 * Relative URLs in the site's page (its stylesheets, images) must resolve against the site, not
 * Carrel, so a <base> goes first in <head>. Any <base> the page carries is removed first.
 */
export function withSiteBase(html: string, siteOrigin: string): string {
  const base = `<base href="${siteOrigin}/">`;
  const stripped = html.replace(/<base\b[^>]*>/gi, "");
  if (/<head\b[^>]*>/i.test(stripped)) return stripped.replace(/<head\b[^>]*>/i, (head) => `${head}${base}`);
  return `${base}${stripped}`;
}

/** A line of plain text at the top of the page saying whose text this is, for a preview of something other than the person's own draft. */
export function withLabel(html: string, label: string): string {
  const note = `<p style="margin:0;padding:8px 12px;font:14px/1.4 system-ui,sans-serif;background:#fff3cd;color:#333;border-bottom:1px solid #d9c27a">${label.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`)}</p>`;
  return /<body\b[^>]*>/i.test(html) ? html.replace(/<body\b[^>]*>/i, (body) => `${body}${note}`) : `${note}${html}`;
}

export function previewResponse(html: string, siteOrigin: string): Response {
  return new Response(withSiteBase(html, siteOrigin), {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Content-Security-Policy": previewPolicy(siteOrigin),
      "X-Frame-Options": "SAMEORIGIN",
    },
  });
}

export function previewFailure(message: string): Response {
  const escaped = message.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);
  return new Response(
    `<!doctype html><html><head><meta charset="utf-8"><title>Preview unavailable</title></head><body><p>${escaped}</p></body></html>`,
    {
      status: 200,
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Content-Security-Policy": "sandbox; default-src 'none'; frame-ancestors 'self'",
        "X-Frame-Options": "SAMEORIGIN",
      },
    },
  );
}

app/root.tsx.source:
import {
  isRouteErrorResponse,
  Links,
  Meta,
  Outlet,
  Scripts,
  ScrollRestoration,
  useRouteLoaderData,
} from "react-router";

import { Empty } from "capsomer/react/empty";

import { getNonce } from "~/lib/context";

import type { Route } from "./+types/root";
import "@fontsource/schibsted-grotesk/400.css";
import "@fontsource/schibsted-grotesk/500.css";
import "@fontsource/schibsted-grotesk/600.css";
import "@fontsource/schibsted-grotesk/800.css";
import "@fontsource/martian-mono/400.css";
import "@fontsource-variable/source-serif-4/index.css";
import "@fontsource-variable/source-serif-4/wght-italic.css";
import "./app.css";

// Run before first paint, so a remembered theme never flashes the other one. It is Capsomer's own
// one-liner (theme-switch.md); the nonce is what lets the policy run it.
const THEME_SCRIPT = 'try{var t=localStorage.getItem("cap-theme");if(t==="light"||t==="dark")document.documentElement.setAttribute("data-theme",t)}catch(e){}';

export function meta(): Route.MetaDescriptors {
  return [{ title: "Carrel" }, { name: "robots", content: "noindex, nofollow" }];
}

// Carried through the loader because Layout cannot reach the request context.
export function loader({ context }: Route.LoaderArgs) {
  return { nonce: getNonce(context) };
}

export function Layout({ children }: { children: React.ReactNode }) {
  // Layout also renders the error boundary, where the loader may not have run. No fallback: a
  // made-up nonce would satisfy the markup while matching nothing in the header.
  const nonce = useRouteLoaderData<typeof loader>("root")?.nonce;
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
        <Meta />
        <Links />
        {nonce ? <script nonce={nonce} dangerouslySetInnerHTML={{ __html: THEME_SCRIPT }} /> : null}
      </head>
      <body>
        {children}
        <ScrollRestoration nonce={nonce} />
        <Scripts nonce={nonce} />
      </body>
    </html>
  );
}

export default function App() {
  return <Outlet />;
}

// The last resort, for an error the shell's own boundary could not hold (the layout itself failed).
export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
  const title = isRouteErrorResponse(error) ? `${error.status} ${error.statusText}` : "Something went wrong";
  return (
    <main className="app-page">
      <Empty kind="failed" title={title} action={<a className="cap-btn" href="/">Go to Home</a>}>
        Nothing you wrote is lost.
      </Empty>
    </main>
  );
}

app/routes/history.tsx.source:
// One item's history: its revisions from the site, newest first, each opening its source; the
// changes between any two; and the person's own working draft set against the site's text or an AI
// draft. Everything here is read-only and works for a Reader. Revision diffs are the site's own
// unified patches; the two comparisons that have both sides in Carrel build the patch here.
// "By word" sets the same two texts against each other sentence by sentence.

import { Link, useLocation, useNavigate, useNavigation } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { DraftCompare, DraftPatch } from "capsomer/react/draft-compare";
import { Empty } from "capsomer/react/empty";
import { Panel } from "capsomer/react/panel";
import { Segmented } from "capsomer/react/segmented";
import { Pill } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

import { DraftLinks } from "~/components/history/draft-links";
import { RevisionPicker } from "~/components/history/revision-picker";
import { PageHead } from "~/components/page-head";
import { listAiDrafts, readAiDraft } from "~/lib/ai.server";
import { readDoc, readDraft } from "~/lib/content.server";
import { getEnv, getViewer } from "~/lib/context";
import { listRevisions, orderPair, readRevision, revisionPatch } from "~/lib/history.server";
import { unifiedPatch } from "~/lib/patch";
import { requireSiteProject } from "~/lib/projects.server";
import { SiteNotConnected } from "~/lib/sites.server";

import type { Route } from "./+types/history";

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `History of ${data.title || data.itemId} · Carrel` : "Carrel" }];
}

type Side = { title: string; who?: string; time?: string; text: string };
type View =
  | { kind: "none" }
  | { kind: "problem"; message: string }
  | { kind: "source"; version: string; message: string; author: string; at: string; source: string; current: boolean; previous: string | null; newest: string | null }
  | { kind: "compare"; heading: string; lead: string; patch: string | null; before: Side | null; after: Side | null };

const utc = (iso: string) => `${iso.slice(0, 16).replace("T", " ")} UTC`;

export async function loader({ params, request, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "read");
  const itemId = params.item;
  const query = new URL(request.url).searchParams;
  const by: "line" | "word" = query.get("by") === "word" ? "word" : "line";

  let doc = null;
  let revisions = null;
  let siteError: string | null = null;
  try {
    doc = await readDoc(env, project, itemId);
    revisions = await listRevisions(env, project, itemId);
  } catch (error) {
    siteError = error instanceof SiteNotConnected ? error.detail : "The site did not answer, so its history cannot be shown.";
  }
  const [draft, aiDrafts] = await Promise.all([readDraft(env.DB, project, viewer, itemId), listAiDrafts(env.DB, project, viewer, itemId)]);
  if (!doc && !draft && aiDrafts.length === 0 && !siteError) throw new Response("Not found", { status: 404 });

  const list = revisions ?? [];
  const picks = query.getAll("v");
  let view: View = { kind: "none" };
  let picked: string[] = [];

  if (query.get("compare") === "site") {
    if (!draft) view = { kind: "problem", message: "You have no working draft of this post in Carrel, so there is nothing to set against the site's text." };
    else if (!doc) view = { kind: "problem", message: siteError ?? "This post is not on the site yet, so there is no site version to compare with." };
    else {
      const before: Side = { title: "On the site", who: doc.status === "published" ? "Published" : doc.status === "scheduled" ? "Scheduled" : "Draft", time: doc.updatedAt ?? undefined, text: doc.source };
      const after: Side = { title: "Your working draft", who: viewer.name, time: draft.updatedAt, text: draft.source };
      view = sides("Your working draft against the site's version", "Your autosaved copy in Carrel, set against what the site holds now.", itemId, before, after, by);
    }
  } else if (query.get("compare") === "ai") {
    const id = Number(query.get("ai"));
    if (!Number.isInteger(id) || id <= 0) {
      view = { kind: "problem", message: "That AI draft is not one of yours for this post." };
    } else {
      const ai = await readAiDraft(env.DB, project, viewer, itemId, id);
      const mine: Side = draft
        ? { title: "Your working draft", who: viewer.name, time: draft.updatedAt, text: draft.source }
        : { title: "On the site", time: doc?.updatedAt ?? undefined, text: doc?.source ?? "" };
      const theirs: Side = { title: `AI draft from ${ai.client}`, who: ai.client, time: ai.createdAt, text: ai.source };
      view = sides(
        `Your ${draft ? "draft" : "post"} against the AI draft from ${ai.client}`,
        draft ? "Your autosaved copy in Carrel, set against the AI draft saved beside it." : "You have no working draft, so this is the site's text against the AI draft saved beside it.",
        itemId,
        mine,
        theirs,
        by,
      );
    }
  } else if (siteError) {
    view = { kind: "none" };
  } else if (query.get("version")) {
    const version = query.get("version")!;
    const at = list.findIndex((r) => r.version === version);
    if (at < 0) {
      view = { kind: "problem", message: "The site has no such revision of this post." };
    } else {
      const revision = list[at]!;
      const source = await readRevision(env, project, itemId, version);
      view =
        source === null
          ? { kind: "problem", message: "The site could not open that revision's source. A site on an older version of the site API cannot." }
          : { kind: "source", version, message: revision.message, author: revision.author, at: revision.at, source, current: at === 0, previous: list[at + 1]?.version ?? null, newest: at === 0 ? null : list[0]!.version };
    }
  } else if (picks.length > 0) {
    const pair = orderPair(list, picks);
    if (!pair) {
      view = { kind: "problem", message: "Pick two different revisions to compare." };
      picked = picks;
    } else {
      picked = [pair.from.version, pair.to.version];
      const heading = `${utc(pair.from.at)} to ${utc(pair.to.at)}`;
      const lead = `What changed on the site between the revision by ${pair.from.author} and the one by ${pair.to.author}.`;
      if (by === "line") {
        const patch = await revisionPatch(env, project, itemId, pair.from.version, pair.to.version);
        view = patch === null ? { kind: "problem", message: "The site could not give the changes between those revisions." } : { kind: "compare", heading, lead, patch, before: null, after: null };
      } else {
        const [before, after] = await Promise.all([readRevision(env, project, itemId, pair.from.version), readRevision(env, project, itemId, pair.to.version)]);
        view =
          before === null || after === null
            ? { kind: "problem", message: "The site could not open one of those revisions' source. A site on an older version of the site API cannot." }
            : {
                kind: "compare",
                heading,
                lead,
                patch: null,
                before: { title: "Earlier revision", who: pair.from.author, time: pair.from.at, text: before },
                after: { title: "Later revision", who: pair.to.author, time: pair.to.at, text: after },
              };
      }
    }
  }

  return {
    project: { slug: project.slug, name: project.name },
    itemId,
    title: doc?.title ?? "",
    by,
    view,
    picked,
    revisions: list.map((r) => ({ version: r.version, at: r.at, author: r.author, message: r.message })),
    siteError,
    againstSite: Boolean(draft && doc),
    aiDrafts: aiDrafts.map((d) => ({ id: d.id, client: d.client, createdAt: d.createdAt })),
  };
}

/** Both texts are in Carrel: the patch is built here, and the same two texts feed the word view. */
function sides(heading: string, lead: string, itemId: string, before: Side, after: Side, by: "line" | "word"): View {
  if (by === "word") return { kind: "compare", heading, lead, patch: null, before, after };
  const patch = unifiedPatch(`${itemId}.md`, { text: before.text, label: before.title }, { text: after.text, label: after.title });
  return { kind: "compare", heading, lead, patch, before: null, after: null };
}

export default function History({ loaderData }: Route.ComponentProps) {
  const { project, itemId, title, by, view, picked, revisions, siteError, aiDrafts, againstSite } = loaderData;
  const editor = `/p/${project.slug}/e/${encodeURIComponent(itemId)}`;
  const historyPath = `${editor}/history`;
  const navigate = useNavigate();
  const location = useLocation();
  // The switch moves at once, while the other view loads; the loader's answer confirms it.
  const pending = useNavigation().location;
  const shown = pending ? (new URLSearchParams(pending.search).get("by") === "word" ? "word" : "line") : by;
  const setBy = (next: "line" | "word") => {
    const params = new URLSearchParams(location.search);
    params.set("by", next);
    void navigate(`${location.pathname}?${params.toString()}`, { preventScrollReset: true });
  };

  return (
    <div className="app-page">
      <PageHead
        crumbs={[{ label: project.name, href: `/p/${project.slug}` }, { label: title || itemId, href: editor }, { label: "History" }]}
        title={`History of ${title || itemId}`}
        lead="What the site remembers of this post, newest first. Looking here changes nothing."
        actions={
          <Link to={editor} className="cap-btn">
            Back to the editor
          </Link>
        }
      />

      {siteError ? <Banner tone="warn">{siteError}</Banner> : null}

      {view.kind === "problem" ? <Alert tone="warn">{view.message}</Alert> : null}

      {view.kind === "source" ? (
        <Panel
          title={view.message || "Revision"}
          src={
            <>
              by {view.author}, <Time at={view.at} format="exact" />
            </>
          }
          actions={
            <>
              {view.current ? <Pill tone="ok">Current</Pill> : null}
              {view.previous ? (
                <Link className="cap-btn" to={`${historyPath}?v=${encodeURIComponent(view.previous)}&v=${encodeURIComponent(view.version)}`}>
                  Changes in this revision
                </Link>
              ) : null}
              {view.newest ? (
                <Link className="cap-btn" to={`${historyPath}?v=${encodeURIComponent(view.version)}&v=${encodeURIComponent(view.newest)}`}>
                  Compare with the current version
                </Link>
              ) : null}
            </>
          }
        >
          <pre className="app-ai-draft" aria-label="Source of this revision">
            {view.source}
          </pre>
        </Panel>
      ) : null}

      {view.kind === "compare" ? (
        <Panel
          title={view.heading}
          description={view.lead}
          actions={<Segmented legend="Compare by" hideLegend size="sm" value={shown} onChange={setBy} options={[{ value: "line", label: "By line" }, { value: "word", label: "By word" }]} />}
        >
          {view.patch !== null ? <DraftPatch patch={view.patch} title={view.heading} id="history-patch" /> : view.before && view.after ? <DraftCompare before={view.before} after={view.after} id="history-compare" /> : null}
        </Panel>
      ) : null}

      {againstSite || aiDrafts.length > 0 ? (
        <Panel title="Your draft" src="Your autosaved copy in Carrel">
          <DraftLinks historyPath={historyPath} againstSite={againstSite} aiDrafts={aiDrafts} />
        </Panel>
      ) : null}

      <Panel title="Revisions" count={revisions.length} src="Saves and publishes on the site">
        {revisions.length === 0 ? (
          <Empty kind="nothing-yet" title="No history to show">
            {siteError ? "The site is not answering." : "The site has no saved revisions of this post yet."}
          </Empty>
        ) : (
          <RevisionPicker revisions={revisions} historyPath={historyPath} picked={picked} label="Revisions of this post" />
        )}
      </Panel>
    </div>
  );
}

app/routes/project.flags.tsx.source:
// Every flag on a site project, in one list (open first): from the checks, from AI sessions and from
// reviewers, including flags on items the site does not have, which no editor page can reach (a proof
// item, a post since deleted). Anyone who can read the project sees them; only the Owner dismisses,
// through the same function as the editor's Dismiss, so a dismissal is recorded the same way.

import { useState, type ReactNode } from "react";
import { Form, Link, useFetcher } from "react-router";
import { Banner } from "capsomer/react/banner";
import { Button } from "capsomer/react/button";
import { ConfirmDialog } from "capsomer/react/confirm-dialog";
import { Empty } from "capsomer/react/empty";
import { Panel } from "capsomer/react/panel";
import { Row, RowList } from "capsomer/react/row-list";
import { Pill, Status } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

import { PageHead } from "~/components/page-head";
import { ProjectTabs } from "~/components/project-tabs";

import { dismissItemFinding, projectFlags } from "~/lib/ai.server";
import { getEnv, getViewer } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";
import { siteEntry } from "~/lib/sites.server";

import type { Route } from "./+types/project.flags";

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `Flags · ${data.project.name} · Carrel` : "Carrel" }];
}

export async function loader({ params, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "read");
  return {
    project: { slug: project.slug, name: project.name, site: siteEntry(project.site).name, mentions: can(project.role, "read_mentions") },
    canDismiss: can(project.role, "publish"),
    flags: await projectFlags(env.DB, project),
  };
}

export async function action({ params, request, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  // The Owner's alone, as in the editor: a dismissed flag no longer holds publish.
  const project = await requireSiteProject(env.DB, viewer, params.project, "publish");
  const form = await request.formData();
  if (form.get("intent") !== "dismiss") throw new Response("Bad request", { status: 400 });
  const id = Number(form.get("flag"));
  const item = String(form.get("item") ?? "");
  if (!Number.isInteger(id) || !item) throw new Response("Bad request", { status: 400 });
  await dismissItemFinding(env.DB, project, viewer, item, id);
  return { dismissed: id };
}

/** Who raised it: a check by name, or the credit an AI session or reviewer put on its message. */
function source(check: string): string {
  if (check === "review") return "Reviewer";
  if (check === "ai") return "AI session";
  return `Check: ${check}`;
}

type Flag = Route.ComponentProps["loaderData"]["flags"][number];

export default function ProjectFlags({ loaderData, actionData }: Route.ComponentProps) {
  const { project, canDismiss, flags } = loaderData;
  const fetcher = useFetcher<typeof action>();
  const [target, setTarget] = useState<{ flag: Flag; opener: HTMLElement | null } | null>(null);
  const open = flags.filter((f) => f.status === "open").length;
  const dismissed = fetcher.data?.dismissed ?? actionData?.dismissed;
  const link = ({ href, children }: { href: string; children: ReactNode }) => <Link to={href}>{children}</Link>;

  return (
    <div className="app-page">
      <PageHead
        title={project.name}
        lead={`${open} open of ${flags.length} flags on ${project.site}. An open flag holds publish until the text is fixed or the Owner dismisses it.`}
      />

      <ProjectTabs slug={project.slug} current="flags" mentions={project.mentions} />

      {dismissed ? <Banner tone="ok">Dismissed flag {dismissed}.</Banner> : null}

      <Panel title="Flags" count={open} src={`${open} open, ${flags.length - open} dismissed`} flush>
        {flags.length === 0 ? (
          <Empty kind="all-clear" flush title={<Status tone="ok">All clear</Status>}>
            No flags on this project.
          </Empty>
        ) : (
          <RowList label="Flags on this project">
            {flags.map((flag) => {
              const isOpen = flag.status === "open";
              return (
                <Row
                  key={flag.id}
                  status={isOpen ? <Status tone="warn">Open</Status> : <Pill variant="secondary">Dismissed</Pill>}
                  title={flag.message}
                  href={flag.onSite ? `/p/${project.slug}/e/${encodeURIComponent(flag.itemId)}` : undefined}
                  renderLink={link}
                  detail={
                    <>
                      {source(flag.check)} on {flag.onSite ? flag.title || flag.itemId : flag.itemId}
                      {flag.onSite ? null : ". Not on the site: no editor page reaches this flag"}
                      {flag.excerpt ? (
                        <>
                          {" "}
                          <q>{flag.excerpt}</q>
                        </>
                      ) : null}
                    </>
                  }
                  meta={<Time at={flag.createdAt} />}
                  actions={
                    isOpen && canDismiss ? (
                      <Form method="post">
                        <input type="hidden" name="flag" value={flag.id} />
                        <input type="hidden" name="item" value={flag.itemId} />
                        <Button
                          type="submit"
                          name="intent"
                          value="dismiss"
                          size="sm"
                          onClick={(event) => {
                            event.preventDefault();
                            setTarget({ flag, opener: event.currentTarget });
                          }}
                        >
                          Dismiss<span className="cap-sr-only"> flag: {flag.message}</span>
                        </Button>
                      </Form>
                    ) : undefined
                  }
                />
              );
            })}
          </RowList>
        )}
      </Panel>

      <ConfirmDialog
        open={target !== null}
        title="Dismiss this flag?"
        lead="A dismissed flag no longer holds publish, and it cannot be reopened."
        body={target ? [target.flag.message] : []}
        action="Dismiss flag"
        returnTo={target?.opener}
        perform={async () => {
          if (!target) return;
          await fetcher.submit({ intent: "dismiss", flag: String(target.flag.id), item: target.flag.itemId }, { method: "post" });
        }}
        onClose={() => setTarget(null)}
      />
    </div>
  );
}

