// The follow-ups after the overnight merges: books through MCP, draft_social_post, a reviewer's flag
// that a recheck must not withdraw, and export refused while an import marker is left in a book.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { exportGate, listFindings, refreshBook, requireBookProject, saveBookFile, type BookProject } from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import type { Viewer } from "~/lib/people.server";
import { createAccount, recordPublication, setSwitches } from "~/lib/social/queue.server";
import { action as fileAction, loader as fileLoader } from "~/routes/book.file";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectAs } from "./mcp-client";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: g\nconflict: c\noutcome: o\n---\n\n";
const SCENE = "chapters/01-arrival/01-the-gate.md";

let gh: ReturnType<typeof fakeNovels>;

async function readDraftOnly(project: BookProject, viewer: Viewer, path: string) {
  return (await readDraft(testEnv.DB, project, viewer, path))?.source;
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  await share(id, reviewer, "reader");
  gh = fakeNovels({
    [`${SLUG}/bible/characters/wade.md`]: "---\nname: Wade\n---\n",
    [`${SLUG}/bible/places/harlan-place.md`]: "---\nname: Harlan place\n---\n",
    [`${SLUG}/${SCENE}`]: `${HEADER}Wade opened the gate.\n`,
  });
  const owner = await viewerFor("owner@test.invalid");
  await refreshBook(testEnv.DB, gh.repo, await requireBookProject(testEnv.DB, owner, SLUG, "read"));
});

async function connect(email: string, client = "Claude") {
  const ai = await connectAs(email, client);
  return ai.call;
}

describe("books through MCP", () => {
  it("lists a book's files with each scene's header, and reads a file with its version", async () => {
    const call = await connect("reader@test.invalid");
    const list = await call("list_book_files", { project: SLUG });
    expect(list.structuredContent).toMatchObject({ files: expect.arrayContaining([{ path: SCENE, kind: "scene", words: 4, header: expect.objectContaining({ pov: "Wade" }), openFlags: 0 }]) });
    const read = await call("read_book_file", { project: SLUG, path: SCENE });
    expect(read.structuredContent).toMatchObject({ path: SCENE, source: `${HEADER}Wade opened the gate.\n`, version: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
  });

  it("PLANT: a stranger's session, and a site's slug, reach no book", async () => {
    await addPerson("stranger@test.invalid");
    expect(await (await connect("stranger@test.invalid"))("list_book_files", { project: SLUG })).toMatchObject({ isError: true });
    await addProject("a-site", "dustinedwards");
    expect(await (await connect("owner@test.invalid"))("list_book_files", { project: "a-site" })).toMatchObject({ isError: true });
  });

  it("runs the checks on text without saving or recording anything", async () => {
    const call = await connect("reader@test.invalid");
    const result = await call("check_book_text", { project: SLUG, path: SCENE, source: `${HEADER}A tapestry.\n` });
    expect(result.structuredContent).toMatchObject({ findings: [{ check: "ai-habits", excerpt: "tapestry" }] });
    const owner = await viewerFor("owner@test.invalid");
    expect(await listFindings(testEnv.DB, await requireBookProject(testEnv.DB, owner, SLUG, "read"))).toEqual([]);
  });

  it("saves an AI draft beside the person's, never over it and never to Git", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "read");
    await autosave(testEnv.DB, project, owner, SCENE, { source: "Dustin's own draft.", baseVersion: null });

    const saved = await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n`, note: "Tighter." });
    expect(saved.structuredContent).toMatchObject({ saved: true, basedOnVersion: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
    expect(await readDraftOnly(project, owner, SCENE)).toBe("Dustin's own draft.");
    expect(gh.commits).toEqual([]);
  });

  it("PLANT: a reviewer's and a Reader's sessions cannot save a book draft", async () => {
    expect(await (await connect("reviewer@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "A reviewer flags; it does not write text. Use add_book_finding." }],
    });
    expect(await (await connect("reader@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({ isError: true });
  });

  it("PLANT: a reviewer's flag on a book file survives the recheck a save runs, and holds export", async () => {
    const reviewer = await connect("reviewer@test.invalid", "Grok Build");
    const flagged = await reviewer("add_book_finding", { project: SLUG, path: SCENE, message: "Wade could not see the gate from the road.", excerpt: "opened the gate" });
    expect(flagged.structuredContent).toMatchObject({ flagged: true, alreadyFlagged: false });

    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    const current = gh.files.get(`${SLUG}/${SCENE}`)!;
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, owner, SCENE, { source: `${HEADER}Wade opened the old gate.\n`, expectedVersion: current.sha });
    expect(saved.ok).toBe(true);
    expect((await listFindings(testEnv.DB, project, { path: SCENE })).map((f) => [f.check, f.status])).toEqual([["review", "open"]]);
    expect(await exportGate(testEnv.DB, project)).toMatchObject({ ok: false, open: 1 });
  });

  it("PLANT: a flag on a path outside the layout is refused", async () => {
    expect(await (await connect("reviewer@test.invalid"))("add_book_finding", { project: SLUG, path: "../x.md", message: "m" })).toMatchObject({ isError: true });
  });
});

describe("AI drafts in the book editor", () => {
  it("shows them beside the text, and Use as my draft makes one the working copy", async () => {
    await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n` });
    vi.stubGlobal("fetch", gh.fetch);
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: testEnv, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("owner@test.invalid"));
    context.set(nonceContext, "n");
    const params = { project: SLUG, "*": SCENE };
    const data = (await fileLoader({ request: new Request("https://carrel.test/"), params, context } as never)) as Awaited<ReturnType<typeof fileLoader>>;
    expect(data.aiDrafts).toMatchObject([{ client: "Claude", source: `${HEADER}An AI version.\n` }]);

    const body = new FormData();
    body.set("intent", "use-ai-draft");
    body.set("draft", String(data.aiDrafts[0]!.id));
    expect(await fileAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context } as never)).toEqual({ intent: "use-ai-draft", used: data.aiDrafts[0]!.id });
    const owner = await viewerFor("owner@test.invalid");
    expect(await readDraftOnly(await requireBookProject(testEnv.DB, owner, SLUG, "read"), owner, SCENE)).toBe(`${HEADER}An AI version.\n`);
  });
});

describe("export refuses a book with import markers", () => {
  it("PLANT: names each file still holding a marker; clean, it passes", async () => {
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\n<!-- import: table: A table was not converted. -->\n\nAfter.\n`);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    await refreshBook(testEnv.DB, gh.repo, project);
    const held = await exportGate(testEnv.DB, project);
    expect(held).toMatchObject({ ok: false });
    expect(held.ok || held.message).toBe(
      "1 file still holds an <!-- import: ... --> marker from the Word import: chapters/01-arrival/02-letter.md. Fix the text there and delete each marker before exporting.",
    );
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\nAfter.\n`);
    await refreshBook(testEnv.DB, gh.repo, project);
    expect(await exportGate(testEnv.DB, project)).toEqual({ ok: true });
  });
});

describe("draft_social_post", () => {
  async function socialAccount() {
    const projectId = await addProject("germomics", "dustinedwards");
    const owner = await viewerFor("owner@test.invalid");
    await createAccount(testEnv.DB, owner, { key: "germomics-bluesky", name: "Germomics", platform: "bluesky", kind: "brand", handle: "g.bsky.social", projectId });
    const row = await testEnv.DB.prepare("SELECT id FROM social_accounts").first<{ id: number }>();
    await setSwitches(testEnv.DB, owner, row!.id, { enabled: true });
    await recordPublication(testEnv.DB, projectId, { id: "ep-1", title: "Episode 1", url: "https://site.test/ep-1", summary: "" });
    return (await testEnv.DB.prepare("SELECT id FROM social_events").first<{ id: number }>())!.id;
  }

  it("stores the Owner's session's draft by event id, credited to the client", async () => {
    const eventId = await socialAccount();
    const result = await (await connect("owner@test.invalid", "Claude Code"))("draft_social_post", { event_id: eventId, text: "Episode 1 is out: https://site.test/ep-1" });
    expect(result.structuredContent).toMatchObject({ stored: true });
    expect(await testEnv.DB.prepare("SELECT source, status, created_by FROM social_posts").first()).toEqual({ source: "predrafted", status: "drafted", created_by: "Claude Code" });
  });

  it("stores by account, project and item too", async () => {
    await socialAccount();
    const result = await (await connect("owner@test.invalid"))("draft_social_post", { account: "germomics-bluesky", project: "germomics", item: "ep-2", text: "Episode 2." });
    expect(result.structuredContent).toMatchObject({ stored: true });
  });

  it("PLANT: an Editor's or a reviewer's session cannot draft social posts", async () => {
    const eventId = await socialAccount();
    for (const email of ["editor@test.invalid", "reviewer@test.invalid"]) {
      expect(await (await connect(email))("draft_social_post", { event_id: eventId, text: "x" })).toMatchObject({
        isError: true,
        content: [{ text: "Social posts are Dustin's: only his own sessions may draft them." }],
      });
    }
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM social_posts").first()).toEqual({ n: 0 });
  });
});

test/people-flags.test.ts.source:
// The people page, the project flags list and media in the authorship record (job_11a70a5353a3).
// Each refusal the job names is planted, and each checks that nothing changed.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { deleteMedia, uploadMedia } from "~/lib/media.server";
import { addPerson as adminAddPerson, listPeople, PeopleRefusal, setDisabled, setProjectRole } from "~/lib/people-admin.server";
import { findViewer } from "~/lib/people.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as peopleAction, loader as peopleLoader } from "~/routes/people";
import { action as flagsAction, loader as flagsLoader } from "~/routes/project.flags";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("stranger@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
  await share(projectId, reviewer, "reader");
});

async function contextFor(email: string, env: Env = testEnv) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}

async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

/** Every people and membership row, to prove a refusal changed nothing. */
async function snapshot() {
  const [p, m] = await Promise.all([
    testEnv.DB.prepare("SELECT id, email, is_owner, is_reviewer, disabled_at FROM people ORDER BY id").all(),
    testEnv.DB.prepare("SELECT project_id, person_id, role FROM project_members ORDER BY project_id, person_id").all(),
  ]);
  return JSON.stringify([p.results, m.results]);
}

function form(fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return new Request("https://carrel.test/people", { method: "POST", body });
}

async function personId(email: string) {
  return (await testEnv.DB.prepare("SELECT id FROM people WHERE email = ?").bind(email).first<{ id: number }>())!.id;
}

describe("the people page", () => {
  it("lists everyone with their kind and their role on each project, the Owner first", async () => {
    const data = await listPeople(testEnv.DB, await viewerFor("owner@test.invalid"));
    expect(data.people[0]).toMatchObject({ email: "owner@test.invalid", isOwner: true });
    expect(data.people.find((p) => p.email === "editor@test.invalid")).toMatchObject({ roles: [{ projectId, role: "editor" }] });
    expect(data.people.find((p) => p.email === "reviewer@test.invalid")).toMatchObject({ isReviewer: true, roles: [{ role: "reader" }] });
    expect(data.projects).toEqual([{ id: projectId, slug: SLUG, name: SLUG, kind: "site" }]);
  });

  it("adds a person, shares a project with them, changes and removes the role, disables and enables them", async () => {
    const context = await contextFor("owner@test.invalid");
    expect(await peopleAction({ request: form({ intent: "add", email: " Wife@Test.Invalid ", name: "Wife", reviewer: "no" }), params: {}, context } as never)).toEqual({
      ok: true,
      intent: "add",
      added: "wife@test.invalid",
    });
    const id = await personId("wife@test.invalid");
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "reader" }), params: {}, context } as never);
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "editor" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT role FROM project_members WHERE person_id = ?").bind(id).first()).toEqual({ role: "editor" });
    await peopleAction({ request: form({ intent: "role", person: String(id), project: String(projectId), role: "" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM project_members WHERE person_id = ?").bind(id).first()).toEqual({ n: 0 });

    await peopleAction({ request: form({ intent: "disable", person: String(id) }), params: {}, context } as never);
    // Disabled means refused at both doors, since every request looks the person up again.
    expect(await findViewer(testEnv.DB, "wife@test.invalid")).toBeNull();
    await peopleAction({ request: form({ intent: "enable", person: String(id) }), params: {}, context } as never);
    expect(await findViewer(testEnv.DB, "wife@test.invalid")).toMatchObject({ email: "wife@test.invalid" });
  });

  it("refuses an email already in Carrel, and one that is not an email", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await snapshot();
    await expect(adminAddPerson(testEnv.DB, owner, { email: "EDITOR@test.invalid", name: "", reviewer: false })).rejects.toBeInstanceOf(PeopleRefusal);
    await expect(adminAddPerson(testEnv.DB, owner, { email: "not an email", name: "", reviewer: false })).rejects.toBeInstanceOf(PeopleRefusal);
    expect(await snapshot()).toBe(before);
  });
});

describe("PLANT: a non-Owner at the people page", () => {
  for (const email of ["editor@test.invalid", "reader@test.invalid", "reviewer@test.invalid", "stranger@test.invalid"]) {
    it(`answers ${email} 404 for the page and every action, and nothing changes`, async () => {
      const before = await snapshot();
      const context = await contextFor(email);
      const target = String(await personId("reader@test.invalid"));
      expect(await status(() => peopleLoader({ request: new Request("https://carrel.test/people"), params: {}, context } as never))).toBe(404);
      for (const fields of <Record<string, string>[]>[
        { intent: "add", email: "new@test.invalid", name: "", reviewer: "no" },
        { intent: "role", person: target, project: String(projectId), role: "editor" },
        { intent: "disable", person: target },
      ]) {
        expect(await status(() => peopleAction({ request: form(fields), params: {}, context } as never)), fields.intent).toBe(404);
      }
      expect(await snapshot()).toBe(before);
    });
  }
});

describe("PLANT: the Owner's own row", () => {
  it("refuses a second Owner: the page has no way to make one, and the database refuses one too", async () => {
    const context = await contextFor("owner@test.invalid");
    // Even a forged form field cannot make an Owner: addPerson has no such input.
    await peopleAction({ request: form({ intent: "add", email: "second@test.invalid", name: "", reviewer: "no", owner: "yes", is_owner: "1" }), params: {}, context } as never);
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM people WHERE is_owner = 1").first()).toEqual({ n: 1 });
    await expect(testEnv.DB.prepare("UPDATE people SET is_owner = 1 WHERE email = 'second@test.invalid'").run()).rejects.toThrow(/UNIQUE/);
  });

  it("refuses the Owner disabling themself, and changing the Owner's role, and nothing changes", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await snapshot();
    await expect(setDisabled(testEnv.DB, owner, owner.id, true)).rejects.toThrow("The Owner cannot be disabled.");
    await expect(setProjectRole(testEnv.DB, owner, owner.id, projectId, "reader")).rejects.toThrow(/Owner's role cannot be changed/);
    const answer = await peopleAction({ request: form({ intent: "disable", person: String(owner.id) }), params: {}, context: await contextFor("owner@test.invalid") } as never);
    expect(answer).toEqual({ ok: false, intent: "disable", message: "The Owner cannot be disabled." });
    expect(await snapshot()).toBe(before);
  });
});

describe("PLANT: a reviewer given the Editor role", () => {
  it("is refused (reviewers read and flag only), and nothing changes; Reader is allowed", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const reviewer = await personId("reviewer@test.invalid");
    await setProjectRole(testEnv.DB, owner, reviewer, projectId, null);
    const before = await snapshot();
    await expect(setProjectRole(testEnv.DB, owner, reviewer, projectId, "editor")).rejects.toThrow(/Reviewers read and flag only/);
    expect(await snapshot()).toBe(before);
    await setProjectRole(testEnv.DB, owner, reviewer, projectId, "reader");
    expect(await testEnv.DB.prepare("SELECT role FROM project_members WHERE person_id = ?").bind(reviewer).first()).toEqual({ role: "reader" });
  });
});

// ---------- the project flags list

async function flag(path: string, message: string, check = "ai") {
  const row = await testEnv.DB.prepare("INSERT INTO findings (project_id, path, check_name, message, fingerprint) VALUES (?, ?, ?, ?, ?) RETURNING id")
    .bind(projectId, path, check, message, `${path}:${message}`)
    .first<{ id: number }>();
  return row!.id;
}

async function indexed(itemId: string, title: string) {
  await testEnv.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, ?, 'post', ?, 'draft', '2026-09-27T00:00:00Z')")
    .bind(projectId, itemId, title)
    .run();
}

function dismissForm(id: number, item: string) {
  const body = new FormData();
  body.set("intent", "dismiss");
  body.set("flag", String(id));
  body.set("item", item);
  return new Request(`https://carrel.test/p/${SLUG}/flags`, { method: "POST", body });
}

describe("the project flags list", () => {
  it("lists every flag, open first, including one on an item the site does not have", async () => {
    await indexed("real-post", "A real post");
    const proof = await flag("carrel-mcp-proof", "Proof flag (from Claude Code)");
    const real = await flag("real-post", "A claim with no source (from Grok Build)", "review");
    const owner = await viewerFor("owner@test.invalid");
    await (await import("~/lib/ai.server")).dismissItemFinding(testEnv.DB, await requireSiteProject(testEnv.DB, owner, SLUG, "publish"), owner, "real-post", real);
    const data = (await flagsLoader({ params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as { canDismiss: boolean; flags: { id: number; onSite: boolean; status: string; title: string | null }[] };
    expect(data.canDismiss).toBe(false);
    expect(data.flags.map((f) => [f.id, f.status, f.onSite, f.title])).toEqual([
      [proof, "open", false, null],
      [real, "dismissed", true, "A real post"],
    ]);
  });

  it("lets the Owner dismiss a flag on an item the site does not have, recorded as the editor records it, and it stays dismissed", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag (from Claude)");
    const owner = await viewerFor("owner@test.invalid");
    expect(await flagsAction({ request: dismissForm(proof, "carrel-mcp-proof"), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)).toEqual({ dismissed: proof });
    const row = await testEnv.DB.prepare("SELECT status, dismissed_by, dismissed_at FROM findings WHERE id = ?").bind(proof).first<{ status: string; dismissed_by: number; dismissed_at: string }>();
    expect(row).toMatchObject({ status: "dismissed", dismissed_by: owner.id });
    expect(row!.dismissed_at).toMatch(/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/);
    const again = (await flagsLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { flags: { id: number; status: string }[] };
    expect(again.flags).toEqual([expect.objectContaining({ id: proof, status: "dismissed" })]);
  });

  it("PLANT: an Editor or a Reader cannot dismiss, a stranger sees nothing, and the flag stays open", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    for (const [email, code] of [["editor@test.invalid", 403], ["reader@test.invalid", 403], ["stranger@test.invalid", 404]] as const) {
      expect(await status(async () => flagsAction({ request: dismissForm(proof, "carrel-mcp-proof"), params: { project: SLUG }, context: await contextFor(email) } as never)), email).toBe(code);
    }
    expect(await status(async () => flagsLoader({ params: { project: SLUG }, context: await contextFor("stranger@test.invalid") } as never))).toBe(404);
    expect(await testEnv.DB.prepare("SELECT status, dismissed_by FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open", dismissed_by: null });
  });

  // Two layers refuse a non-Owner: the route (by role, before it reads the form) and the dismiss
  // function itself. Each is tested on its own, so removing either one is seen.
  it("PLANT: the route refuses a non-Owner by role before it reads the form", async () => {
    const empty = new Request(`https://carrel.test/p/${SLUG}/flags`, { method: "POST", body: new FormData() });
    // With the role check, 403. Without it, the missing fields would answer 400 instead.
    expect(await status(async () => flagsAction({ request: empty, params: { project: SLUG }, context: await contextFor("editor@test.invalid") } as never))).toBe(403);
  });

  it("PLANT: the dismiss function refuses a non-Owner on its own, whatever route calls it", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    const editor = await viewerFor("editor@test.invalid");
    const { dismissItemFinding } = await import("~/lib/ai.server");
    const project = await requireSiteProject(testEnv.DB, editor, SLUG, "read");
    expect(await status(() => dismissItemFinding(testEnv.DB, project, editor, "carrel-mcp-proof", proof))).toBe(403);
    expect(await testEnv.DB.prepare("SELECT status FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open" });
  });

  it("refuses a flag named with the wrong item, so a form cannot dismiss another item's flag", async () => {
    const proof = await flag("carrel-mcp-proof", "Proof flag");
    expect(await status(async () => flagsAction({ request: dismissForm(proof, "some-other-item"), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never))).toBe(404);
    expect(await testEnv.DB.prepare("SELECT status FROM findings WHERE id = ?").bind(proof).first()).toEqual({ status: "open" });
  });
});

// ---------- media in the authorship record

const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

describe("media in the authorship record", () => {
  let site: ReturnType<typeof fakeSite>;
  let env: Env;

  beforeEach(() => {
    site = fakeSite();
    env = connectedEnv();
    vi.stubGlobal("fetch", site.fetch);
  });

  const rows = () => testEnv.DB.prepare("SELECT id, item_id, person_id, action, version_before, version_after, client FROM changes ORDER BY created_at").all().then((r) => r.results);
  const file = (bytes: Uint8Array, name = "river.png", type = "image/png") => ({ name, type, size: bytes.byteLength, bytes: async () => bytes.slice().buffer });

  it("writes exactly one row for an upload and one for a delete, crediting the person and an AI client", async () => {
    const editor = await viewerFor("editor@test.invalid");
    const up = await uploadMedia(env, await requireSiteProject(env.DB, editor, SLUG, "edit"), { viewer: editor, client: "Claude Code" }, file(PNG), "The river");
    expect(up.ok).toBe(true);
    const id = up.ok ? up.item.id : "";
    expect(await rows()).toEqual([{ id: expect.any(String), item_id: id, person_id: editor.id, action: "media-upload", version_before: null, version_after: null, client: "Claude Code" }]);

    const owner = await viewerFor("owner@test.invalid");
    expect(await deleteMedia(env, await requireSiteProject(env.DB, owner, SLUG, "delete_media"), { viewer: owner }, id)).toEqual({ ok: true });
    expect((await rows()).map((r) => [r.action, r.item_id, r.person_id, r.client])).toEqual([
      ["media-upload", id, editor.id, "Claude Code"],
      ["media-delete", id, owner.id, null],
    ]);
  });

  it("PLANT: a refused delete, a refused upload and a role refusal write no row", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const item = await site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: "cover.png", alt: "", changeId: "seed" });
    await site.adapter.content.saveDraft("river-post", { source: `# The river\n\n![](${item.url})\n`, expectedVersion: null, changeId: "c1" });
    const project = await requireSiteProject(env.DB, owner, SLUG, "delete_media");
    expect(await deleteMedia(env, project, { viewer: owner }, item.id)).toMatchObject({ ok: false, usedBy: [{ id: "river-post" }] });
    expect(await uploadMedia(env, project, { viewer: owner }, file(new TextEncoder().encode("<p>x</p>"), "x.html", "text/html"), "")).toMatchObject({ ok: false });
    const reader = await viewerFor("reader@test.invalid");
    expect(await status(async () => uploadMedia(env, await requireSiteProject(env.DB, reader, SLUG, "read"), { viewer: reader }, file(PNG), ""))).toBe(403);
    expect(await rows()).toEqual([]);
  });

  it("still requires a version for every content write (migration 0007 keeps that rule)", async () => {
    const owner = await personId("owner@test.invalid");
    await expect(
      testEnv.DB.prepare("INSERT INTO changes (id, project_id, item_id, person_id, action, version_after) VALUES ('x', ?, 'post', ?, 'save', NULL)").bind(projectId, owner).run(),
    ).rejects.toThrow(/CHECK/);
    await testEnv.DB.prepare("INSERT INTO changes (id, project_id, item_id, person_id, action, version_after) VALUES ('y', ?, 'post', ?, 'save', 'v1')").bind(projectId, owner).run();
  });
});

test/media-writes.test.ts.source:
// The media library's v0.4.0 writes (job_b4acbaabf747): alt text, tags, the trash, bulk actions and
// emptying the trash, over site-api's own handler and its reference adapter. Planted: the Owner-only
// boundary (a delete, a bulk delete and an empty-trash by an Editor are refused before the site hears
// anything), a stale version (plain conflict, nothing recorded), per-file bulk reporting (a file a post
// uses is refused alone, with the post named), and a site that offers none of the writes.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { bulkMedia, emptyMediaTrash, listMedia, mediaMeta, parseMediaTags, restoreMedia, setMediaAlt, setMediaTags, trashMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as bulkRoute } from "~/routes/media.bulk";
import { action as mediaAction, loader as mediaLoader } from "~/routes/media";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

let site: ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  site = fakeSite();
  env = connectedEnv();
  vi.stubGlobal("fetch", site.fetch);
});

async function project(email: string) {
  return requireSiteProject(env.DB, await viewerFor(email), SLUG, "read");
}
async function actor(email: string) {
  return { viewer: await viewerFor(email) };
}
async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}
async function contextFor(email: string) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}
async function seedFile(name = "river.png") {
  const item = await site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: name, alt: "", changeId: `seed-${name}` });
  return { ...item, version: (await site.adapter.media!.get(item.id))!.version! };
}
async function useInPost(url: string, slug = "river-post") {
  await site.adapter.content.saveDraft(slug, { source: `---\ntitle: The river\n---\nIntro.\n\n:::figure{src="${url}" alt="The river"}\n:::\n`, expectedVersion: null, changeId: `c-${slug}` });
}
const rows = async () =>
  (await testEnv.DB.prepare("SELECT id, action, item_id AS itemId, version_before AS vb, version_after AS va, person_id AS who FROM changes ORDER BY rowid").all<{ id: string; action: string; itemId: string; vb: string | null; va: string | null; who: number }>()).results;
const sitePosts = () => site.requests.filter((r) => !r.startsWith("GET"));

async function post(path: string, fields: Record<string, string | string[]>, email: string, route: "media" | "bulk" = "media") {
  const form = new FormData();
  for (const [k, v] of Object.entries(fields)) for (const one of Array.isArray(v) ? v : [v]) form.append(k, one);
  const request = new Request(`https://carrel.test/p/${SLUG}/${path}`, { method: "POST", body: form });
  const args = { request, params: { project: SLUG }, context: await contextFor(email) } as never;
  return route === "media" ? mediaAction(args) : bulkRoute(args);
}

describe("alt text, tags, trash and restore", () => {
  it("writes each as an Editor with the version seen, and records who did it", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");

    const alt = await setMediaAlt(env, editor, who, file.id, "The river at dusk", file.version);
    expect(alt).toMatchObject({ ok: true });
    const tags = await setMediaTags(env, editor, who, file.id, ["river", "dusk"], alt.ok ? alt.version : "");
    expect(tags.ok).toBe(true);
    const trashed = await trashMedia(env, editor, who, file.id, tags.ok ? tags.version : "");
    expect(trashed.ok).toBe(true);
    expect((await listMedia(env, editor, {})).items).toEqual([]);
    expect((await listMedia(env, editor, { trashed: "only" })).items).toMatchObject([{ id: file.id, alt: "The river at dusk", tags: ["dusk", "river"] }]);
    expect((await restoreMedia(env, editor, who, file.id, trashed.ok ? trashed.version : "")).ok).toBe(true);
    expect((await listMedia(env, editor, { tag: "dusk" })).items).toHaveLength(1);

    const editorId = (await viewerFor("editor@test.invalid")).id;
    expect((await rows()).map((r) => [r.action, r.itemId, r.who === editorId])).toEqual([
      ["media-alt", file.id, true],
      ["media-tags", file.id, true],
      ["media-trash", file.id, true],
      ["media-restore", file.id, true],
    ]);
    expect((await rows())[0]).toMatchObject({ vb: file.version, va: alt.ok ? alt.version : "x" });
  });

  it("refuses a Reader before the site hears anything, and records nothing", async () => {
    const file = await seedFile();
    const reader = await project("reader@test.invalid");
    const who = await actor("reader@test.invalid");
    site.requests.length = 0;
    expect(await status(() => setMediaAlt(env, reader, who, file.id, "x", file.version))).toBe(403);
    expect(await status(() => trashMedia(env, reader, who, file.id, file.version))).toBe(403);
    expect(await status(() => bulkMedia(env, reader, who, "trash", [{ id: file.id, version: file.version }]))).toBe(403);
    expect(sitePosts()).toEqual([]);
    expect(await rows()).toEqual([]);
  });

  it("says a stale version plainly, changes nothing and records nothing", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    await setMediaAlt(env, editor, who, file.id, "first", file.version);
    const stale = await setMediaAlt(env, editor, who, file.id, "second", file.version);
    expect(stale).toMatchObject({ ok: false, conflict: true, message: expect.stringContaining("changed on the site") });
    expect((await site.adapter.media!.get(file.id))!.alt).toBe("first");
    expect(await rows()).toHaveLength(1);
  });

  it("answers the page's form with the conflict, and refuses a tag the site would not spell", async () => {
    const file = await seedFile();
    await post("media", { intent: "set-alt", id: file.id, version: file.version, alt: "first" }, "editor@test.invalid");
    expect(await post("media", { intent: "set-alt", id: file.id, version: file.version, alt: "second" }, "editor@test.invalid")).toMatchObject({ intent: "set-alt", ok: false, conflict: true });
    const fresh = (await site.adapter.media!.get(file.id))!.version!;
    expect(await post("media", { intent: "set-tags", id: file.id, version: fresh, tags: "Good Tag, bad/tag" }, "editor@test.invalid")).toMatchObject({ ok: false, message: expect.stringContaining("cannot be a tag") });
    expect(parseMediaTags("River, good tag,river")).toEqual({ ok: true, tags: ["river", "good-tag"] });
  });
});

describe("PLANT: only the Owner deletes for good or empties the trash", () => {
  it("refuses an Editor's bulk delete and empty-trash before the site hears anything, and the files stay", async () => {
    const a = await seedFile("a.png");
    const trashed = await trashMedia(env, await project("owner@test.invalid"), await actor("owner@test.invalid"), a.id, a.version);
    expect(trashed.ok).toBe(true);
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    const before = await rows();
    site.requests.length = 0;

    expect(await status(() => bulkMedia(env, editor, who, "delete", [{ id: a.id }]))).toBe(403);
    expect(await status(() => emptyMediaTrash(env, editor, who))).toBe(403);
    expect(await status(() => post("media", { intent: "empty-trash", confirm: "empty" }, "editor@test.invalid"))).toBe(403);
    expect(await (await post("media/bulk", { op: "delete", item: `${a.id}\t` }, "editor@test.invalid", "bulk") as Response).status).toBe(403);
    expect(sitePosts()).toEqual([]);
    expect(site.adapter.mediaStore.has(a.id)).toBe(true);
    expect(site.adapter.deleted).toEqual([]);
    expect(await rows()).toEqual(before);
  });

  it("lets the Owner empty the trash only after confirming, then deletes what the site lets go and records each file", async () => {
    const gone = await seedFile("gone.png");
    const used = await seedFile("used.png");
    await useInPost(used.url);
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");
    await trashMedia(env, owner, who, gone.id, gone.version);
    await trashMedia(env, owner, who, used.id, used.version);

    expect(await post("media", { intent: "empty-trash" }, "owner@test.invalid")).toEqual({ intent: "empty-trash", needsConfirm: true });
    expect(site.adapter.deleted).toEqual([]);

    const done = await post("media", { intent: "empty-trash", confirm: "empty" }, "owner@test.invalid");
    expect(done).toMatchObject({ intent: "empty-trash", ok: true, deleted: [gone.id], refused: [{ id: used.id, usedBy: [{ id: "river-post", title: "The river" }] }], more: false });
    expect(site.adapter.mediaStore.has(used.id)).toBe(true);
    const deletes = (await rows()).filter((r) => r.action === "media-delete");
    expect(deletes).toMatchObject([{ itemId: gone.id }]);
    // The site numbers files by their place in the trash it lists, refused ones included: the used file is first (newest), this one second.
    expect(deletes[0]!.id).toMatch(/-2$/);
  });
});

describe("bulk actions report each file", () => {
  it("trashes the fresh file, leaves the stale one, and records only what was done", async () => {
    const a = await seedFile("a.png");
    const b = await seedFile("b.png");
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    await setMediaAlt(env, editor, who, b.id, "moved on", b.version); // b is now stale for anyone holding the old version
    const results = await bulkMedia(env, editor, who, "trash", [
      { id: a.id, version: a.version },
      { id: b.id, version: b.version },
      { id: "uploads/missing.png", version: "m99" },
    ]);
    expect(results.map((r) => [r.id, r.ok])).toEqual([[a.id, true], [b.id, false], ["uploads/missing.png", false]]);
    expect(results[1]!.message).toContain("changed on the site");
    expect((await rows()).filter((r) => r.action === "media-trash").map((r) => r.itemId)).toEqual([a.id]);
    expect((await listMedia(env, editor, {})).items.map((i) => i.id)).toEqual([b.id]);
  });

  it("names the post that blocks a bulk delete, deletes the rest, and tags in bulk", async () => {
    const free = await seedFile("free.png");
    const used = await seedFile("used.png");
    await useInPost(used.url);
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");

    const tagged = await bulkMedia(env, owner, who, "add-tags", [{ id: free.id, version: free.version }, { id: used.id, version: used.version }], ["spring", "river"]);
    expect(tagged.every((r) => r.ok)).toBe(true);
    expect((await listMedia(env, owner, { tag: "spring" })).items).toHaveLength(2);

    const results = await bulkMedia(env, owner, who, "delete", [{ id: free.id }, { id: used.id }]);
    expect(results.find((r) => r.id === free.id)).toMatchObject({ ok: true });
    expect(results.find((r) => r.id === used.id)).toMatchObject({ ok: false, usedBy: [{ type: "post", id: "river-post", title: "The river" }] });
    expect(site.adapter.deleted).toEqual([free.id]);
    expect((await rows()).filter((r) => r.action === "media-delete").map((r) => r.itemId)).toEqual([free.id]);
  });

  it("answers the endpoint's JSON: a bad action and a bad tag are 400, and a good one lists every file", async () => {
    const a = await seedFile("a.png");
    expect(((await post("media/bulk", { op: "burn", item: a.id }, "editor@test.invalid", "bulk")) as Response).status).toBe(400);
    expect(((await post("media/bulk", { op: "add-tags", item: `${a.id}\t${a.version}`, tags: "no/good" }, "editor@test.invalid", "bulk")) as Response).status).toBe(400);
    const ok = (await post("media/bulk", { op: "trash", item: `${a.id}\t${a.version}` }, "editor@test.invalid", "bulk")) as Response;
    expect(await ok.json()).toMatchObject({ results: [{ id: a.id, ok: true }] });
  });
});

describe("a site that offers none of the writes", () => {
  beforeEach(() => {
    site = fakeSite(memoryAdapter({ mediaWrites: false }));
    vi.stubGlobal("fetch", site.fetch);
  });

  it("is told so by its meta, so the page shows no alt, tag, trash or selection tools", async () => {
    expect((await mediaMeta(env, await project("owner@test.invalid")))!.offers).toEqual({ alt: false, tags: false, trash: false });
    await seedFile();
    const data = (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media?view=trash`), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { offers: unknown; view: string; items: unknown[] };
    expect(data.offers).toEqual({ alt: false, tags: false, trash: false });
    expect(data.view).toBe("library"); // no Trash view to open
    expect(data.items).toHaveLength(1);
  });

  it("answers a write that arrives anyway with 'not offered', not a crash", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    expect(await trashMedia(env, editor, await actor("editor@test.invalid"), file.id, "m1")).toMatchObject({ ok: false, message: "This site does not offer that." });
    expect(await rows()).toEqual([]);
  });
});

describe("the page's loader", () => {
  it("offers the writes the site has, lists the trash on its own view, and filters by tag", async () => {
    const a = await seedFile("a.png");
    const b = await seedFile("b.png");
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");
    await setMediaTags(env, owner, who, a.id, ["river"], a.version);
    await trashMedia(env, owner, who, b.id, b.version);
    const load = async (query: string, email = "owner@test.invalid") =>
      (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media${query}`), params: { project: SLUG }, context: await contextFor(email) } as never)) as {
        offers: unknown;
        view: string;
        items: { id: string }[];
        trashFiles: { id: string }[];
        tag: string;
        tagInvalid: boolean;
      };
    const library = await load("");
    expect(library.offers).toEqual({ alt: true, tags: true, trash: true });
    expect(library.items.map((i) => i.id)).toEqual([a.id]);
    const trash = await load("?view=trash");
    expect(trash).toMatchObject({ view: "trash", items: [{ id: b.id }], trashFiles: [{ id: b.id }] });
    expect((await load("?tag=river")).items.map((i) => i.id)).toEqual([a.id]);
    expect((await load("?tag=nothing")).items).toEqual([]);
    expect(await load("?tag=Not%20a/tag")).toMatchObject({ tag: "", tagInvalid: true });
    // An Editor sees the trash but is not handed the list that names every file for the empty-trash confirm.
    expect((await load("?view=trash", "editor@test.invalid")).trashFiles).toEqual([]);
  });
});

test/history.test.ts.source:
// The history screens, driven through the route's loader with a real request context: a Reader may
// read all of it, nothing in it writes (to the site or to Carrel), and each comparison names the
// right two texts, older first.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave, writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { orderPair } from "~/lib/history.server";
import { hasChanges, unifiedPatch } from "~/lib/patch";
import { requireSiteProject } from "~/lib/projects.server";
import { loader as historyLoader } from "~/routes/history";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let versions: string[];

const V1 = "---\ntitle: Post one\n---\nFirst words.\n";
const V2 = "---\ntitle: Post one\n---\nFirst words, revised.\n";
const V3 = "---\ntitle: Post one\n---\nFirst words, revised.\n\nA new closing paragraph.\n";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, reader, "reader");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const owner = await viewerFor("owner@test.invalid");
  const project = await requireSiteProject(testEnv.DB, owner, SLUG, "publish");
  versions = [];
  let expected: string | null = null;
  for (const source of [V1, V2, V3]) {
    const saved = await writeToSite(env, project, owner, "post-one", { action: "save", source, expectedVersion: expected }, site.fetch);
    if (!saved.ok) throw new Error(saved.message);
    expected = saved.version;
    versions.push(saved.version);
  }
  site.requests.length = 0;
});

async function load(email: string, search = "") {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/history${search}`);
  return historyLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never);
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

const changeRows = async () => (await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>())!.n;

describe("reading history", () => {
  it("lists the revisions newest first for a Reader, and only reads", async () => {
    const before = await changeRows();
    const data = await load("reader@test.invalid");
    expect(data.revisions.map((r) => r.version)).toEqual([...versions].reverse());
    expect(data.revisions).toHaveLength(3);
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
    expect(await changeRows()).toBe(before);
  });

  it("opens the source of an old revision", async () => {
    const data = await load("reader@test.invalid", `?version=${versions[0]}`);
    expect(data.view).toMatchObject({ kind: "source", source: V1, current: false, previous: null, newest: versions[2] });
    const newest = await load("reader@test.invalid", `?version=${versions[2]}`);
    expect(newest.view).toMatchObject({ kind: "source", source: V3, current: true, previous: versions[1], newest: null });
  });

  it("says plainly when the revision is not one the site holds", async () => {
    const data = await load("reader@test.invalid", "?version=nope");
    expect(data.view).toMatchObject({ kind: "problem", message: "The site has no such revision of this post." });
  });

  it("is answered 404 to someone with no role on the project, before the site is asked", async () => {
    expect(await refusal(load("stranger@test.invalid"))).toBe(404);
    expect(site.requests).toEqual([]);
  });
});

describe("comparing revisions", () => {
  it("sets the older revision against the newer whichever was picked first, from the site's own patch", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[2]}&v=${versions[0]}`);
    expect(data.picked).toEqual([versions[0], versions[2]]);
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-First words.\n");
    expect(patch).toContain("+First words, revised.\n");
    expect(patch).toContain("+A new closing paragraph.\n");
    expect(site.requests).toContain("GET /api/carrel/v1/content/post-one/diff");
  });

  it("by word, hands the two revisions' texts to the word compare, older as Before", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[0]}&v=${versions[1]}&by=word`);
    expect(data.view).toMatchObject({ kind: "compare", patch: null, before: { text: V1 }, after: { text: V2 } });
  });

  it("refuses one pick, the same pick twice and a pick the site does not hold, in words", async () => {
    for (const search of [`?v=${versions[0]}`, `?v=${versions[0]}&v=${versions[0]}`, `?v=${versions[0]}&v=nope`]) {
      const data = await load("reader@test.invalid", search);
      expect(data.view, search).toMatchObject({ kind: "problem", message: "Pick two different revisions to compare." });
    }
  });

  it("orders a pair by the site's list, newest first, so the older is always from", () => {
    const list = [
      { version: "c", at: "2026-10-03T00:00:00Z", author: "a", message: "" },
      { version: "b", at: "2026-10-02T00:00:00Z", author: "a", message: "" },
      { version: "a", at: "2026-10-01T00:00:00Z", author: "a", message: "" },
    ];
    expect(orderPair(list, ["c", "a"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a", "c"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a"])).toBeNull();
    expect(orderPair(list, ["a", "a"])).toBeNull();
    expect(orderPair(list, ["a", "z"])).toBeNull();
  });
});

describe("comparing the working draft", () => {
  async function ownDraft(source: string) {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "edit");
    await autosave(testEnv.DB, project, owner, "post-one", { source, baseVersion: versions[2]! });
    return { owner, project };
  }

  it("sets the draft against the site's text with a patch built here, and the site is only read", async () => {
    await ownDraft(V3.replace("A new closing paragraph.", "A different closing paragraph."));
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-A new closing paragraph.\n");
    expect(patch).toContain("+A different closing paragraph.\n");
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
  });

  it("says there is nothing to compare when the person has no working draft", async () => {
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view).toMatchObject({ kind: "problem" });
    expect((data.view as { message: string }).message).toMatch(/no working draft/);
  });

  it("sets the draft against an AI draft, and a draft that is not the viewer's is not found", async () => {
    const { owner, project } = await ownDraft(V3);
    const saved = await saveAiDraft(env, project, { viewer: owner, client: "Claude Code" }, "post-one", { source: V3.replace("First words, revised.", "First words, tightened."), note: "" }, site.fetch);
    const data = await load("owner@test.invalid", `?compare=ai&ai=${saved.id}`);
    const view = data.view as { kind: string; heading: string; patch: string };
    expect(view.kind).toBe("compare");
    expect(view.heading).toContain("AI draft from Claude Code");
    expect(view.patch).toContain("-First words, revised.\n");
    expect(view.patch).toContain("+First words, tightened.\n");
    expect(await refusal(load("reader@test.invalid", `?compare=ai&ai=${saved.id}`))).toBe(404);
  });
});

describe("the local patch", () => {
  it("names both sides but one file, shows only the changed lines with context, and says nothing changed when nothing did", () => {
    const patch = unifiedPatch("post-one.md", { text: "a\nb\nc\nd\ne\nf\ng\nh\n", label: "On the site" }, { text: "a\nb\nc\nD\ne\nf\ng\nh\n", label: "Your draft" });
    expect(patch).toContain("--- post-one.md\tOn the site");
    expect(patch).toContain("+++ post-one.md\tYour draft");
    expect(patch).toContain("-d\n+D\n");
    expect(hasChanges(patch)).toBe(true);
    const same = unifiedPatch("post-one.md", { text: "same\n", label: "a" }, { text: "same\n", label: "b" });
    expect(hasChanges(same)).toBe(false);
  });
});

test/legal.test.ts.source:
// Legal pages: shared sections written into each site's page, the fields they take, the date stamped
// on an Owner publish of a changed text, and the page the site's data license names that Carrel never
// takes down or moves. The write tests run Carrel's real code against site-api's reference site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { readFields, splitSource } from "~/lib/frontmatter";
import { expandShared, legalTypeOf, prepareLegalWrite, sectionsUsed, type SharedSection } from "~/lib/legal";
import { deleteSection, listSections, saveSection } from "~/lib/legal.server";
import { requireSiteProject } from "~/lib/projects.server";
import { siteEntry } from "~/lib/sites.server";
import { action as legalAction, loader as legalLoader } from "~/routes/legal";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

const SECTIONS: SharedSection[] = [
  { key: "hosting", title: "Hosting", body: "{{site_name}} runs on Cloudflare. Questions go to {{contact}}." },
  { key: "analytics", title: "Analytics", body: "Cloudflare Web Analytics counts visits without tracking cookies." },
];

const FRONT = ["---", "path: /privacy", 'title: "Privacy"', "legal_type: privacy", 'site_name: "dustinedwards.info"', 'contact: "hello@example.test"', "---", ""].join("\n");

describe("expandShared", () => {
  it("writes each section between its markers with the page's fields filled in", () => {
    const out = expandShared("Intro.\n\n<!-- shared:hosting -->\n", SECTIONS, { site_name: "dustinedwards.info", contact: "hello@example.test" });
    expect(out.text).toBe(
      "Intro.\n\n<!-- shared:hosting -->\ndustinedwards.info runs on Cloudflare. Questions go to hello@example.test.\n<!-- /shared:hosting -->\n",
    );
    expect(out.unknownSections).toEqual([]);
    expect(out.missingFields).toEqual([]);
  });

  it("gives the same text when run again, so a page is expanded on every write", () => {
    const values = { site_name: "A", contact: "b@example.test" };
    const once = expandShared("<!-- shared:hosting -->\n\n<!-- shared:analytics -->\n", SECTIONS, values).text;
    expect(expandShared(once, SECTIONS, values).text).toBe(once);
    expect(sectionsUsed(once)).toEqual(["hosting", "analytics"]);
  });

  it("replaces text a person typed inside the markers, since the section is the source", () => {
    const out = expandShared("<!-- shared:analytics -->\nold wording\n<!-- /shared:analytics -->", SECTIONS, {});
    expect(out.text).not.toContain("old wording");
  });

  it("names an unknown section and a missing field, and leaves both as written", () => {
    const out = expandShared("<!-- shared:nope -->\n<!-- shared:hosting -->", SECTIONS, { site_name: "A" });
    expect(out.unknownSections).toEqual(["nope"]);
    expect(out.missingFields).toEqual(["contact"]);
    expect(out.text).toContain("<!-- shared:nope -->");
    expect(out.text).toContain("{{contact}}");
  });
});

describe("prepareLegalWrite", () => {
  const base = { sections: SECTIONS, today: "2026-10-06" };

  it("stamps last_updated when the Owner publishes a changed text", () => {
    const result = prepareLegalWrite({ ...base, source: `${FRONT}New.\n`, stored: `${FRONT}Old.\n`, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("leaves the date alone when only a field changed", () => {
    const stored = `${FRONT}Same.\n`;
    const result = prepareLegalWrite({ ...base, source: stored.replace("hello@example.test", "other@example.test"), stored, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("stamps a draft that goes public even if its text was already saved", () => {
    const stored = `${FRONT}Saved earlier.\n`;
    const result = prepareLegalWrite({ ...base, source: stored, stored, storedPublic: false, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("does not stamp a draft save, and keeps a missing field's token so no work is lost", () => {
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const result = prepareLegalWrite({ ...base, source, stored: null, storedPublic: false, public: false });
    expect(result.ok && result.source).toContain("{{contact}}");
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("refuses to go public with a field missing or a section unknown, and says which", () => {
    const missing = prepareLegalWrite({ ...base, source: FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n", stored: null, storedPublic: false, public: true });
    expect(!missing.ok && missing.message).toContain("contact");
    const unknown = prepareLegalWrite({ ...base, source: `${FRONT}<!-- shared:nope -->\n`, stored: null, storedPublic: false, public: true });
    expect(!unknown.ok && unknown.message).toContain('"nope"');
  });

  it("recognises a legal page by its legal_type", () => {
    expect(legalTypeOf(FRONT)).toBe("privacy");
    expect(legalTypeOf("---\ntitle: x\n---\n")).toBeNull();
    expect(legalTypeOf("no frontmatter")).toBeNull();
  });
});

let projectId: number;
let ownerId: number;

beforeEach(async () => {
  await resetDb();
  ownerId = await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  for (const s of SECTIONS) {
    await testEnv.DB.prepare("INSERT INTO legal_sections (key, title, body, updated_by) VALUES (?, ?, ?, ?)").bind(s.key, s.title, s.body, ownerId).run();
  }
});

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

async function seed(site: ReturnType<typeof fakeSite>, id: string, source: string) {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(connectedEnv(), project, viewer, id, { action: "save", source, expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  return saved.version;
}

const writes = (site: ReturnType<typeof fakeSite>) => site.requests.filter((r) => !r.startsWith("GET"));

describe("a legal page written to the site", () => {
  it("is published with its shared sections filled in and its date stamped, through the real write path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n\n<!-- shared:hosting -->\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version }, site.fetch);
    expect(published.ok).toBe(true);
    // A publish with no text sends the stored text, so the stored text is what the draft save wrote.
    const doc = await site.adapter.content.get("page.privacy");
    expect(doc?.source).toContain("dustinedwards.info runs on Cloudflare. Questions go to hello@example.test.");
    expect(doc?.status).toBe("published");
  });

  it("stamps last_updated when the text sent with a publish changed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source: `${FRONT}Changed.\n` }, site.fetch);
    expect(published.ok).toBe(true);
    expect(readFields(splitSource((await site.adapter.content.get("page.privacy"))!.source).front).last_updated).toBe(new Date().toISOString().slice(0, 10));
  });

  it("is refused at publish with a field missing, and the site hears no write after the seed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const version = await seed(site, "page.privacy", source);
    const before = writes(site).length;
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source }, site.fetch);
    expect(published).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
  });

  it("is an ordinary item for an AI session: no special refusal, the same role rules", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("editor@test.invalid");
    const saved = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "save", source: `${FRONT}Draft text.\n`, expectedVersion: null }, site.fetch, { client: "claude" });
    expect(saved.ok).toBe(true);
  });
});

describe("PLANT: the page the site's data license names", () => {
  const TERMS = ["---", "path: /terms", 'title: "Terms"', "legal_type: terms", "---", "The terms.", ""].join("\n");

  it("cannot be unpublished through Carrel, and the site hears nothing", async () => {
    expect(siteEntry("dustinedwards").keepPublic).toContain("page.terms");
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "publish", expectedVersion: version }, site.fetch);
    if (!published.ok) throw new Error(published.message);
    const before = writes(site).length;
    const result = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "unpublish", expectedVersion: published.version }, site.fetch);
    expect(result).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
    expect((await site.adapter.content.get("page.terms"))?.status).toBe("published");
  });

  it("can have its wording changed, but not its path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
    expect((moved as { message: string }).message).toContain("/terms");
    const reworded = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("The terms.", "Better terms."), expectedVersion: version }, site.fetch);
    expect(reworded.ok).toBe(true);
  });

  it("is guarded by id even when its legal_type is removed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("legal_type: terms\n", "").replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
  });
});

describe("the shared sections", () => {
  it("are changed only by the Owner", async () => {
    const editor = await as("editor@test.invalid");
    await expect(saveSection(testEnv.DB, editor.project, editor.viewer, { key: "x", title: "X", body: "Text." })).rejects.toMatchObject({ status: 403 });
    await expect(deleteSection(testEnv.DB, editor.project, "hosting")).rejects.toMatchObject({ status: 403 });
    const owner = await as("owner@test.invalid");
    expect(await saveSection(testEnv.DB, owner.project, owner.viewer, { key: "x", title: "X", body: "Text." })).toEqual({ ok: true });
    expect((await listSections(testEnv.DB)).map((s) => s.key)).toEqual(["analytics", "hosting", "x"]);
  });

  it("refuse a bad name, an empty text and a wide dash", async () => {
    const owner = await as("owner@test.invalid");
    for (const input of [
      { key: "Bad Name", title: "T", body: "B" },
      { key: "ok", title: "", body: "B" },
      { key: "ok", title: "T", body: "One — two." },
    ]) {
      expect((await saveSection(testEnv.DB, owner.project, owner.viewer, input)).ok).toBe(false);
    }
  });
});

describe("the Legal tab", () => {
  async function contextFor(email: string) {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: connectedEnv(), ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor(email));
    context.set(nonceContext, "test-nonce");
    return context;
  }

  it("lists each legal page, says which are not set up, and flags a page behind the shared text", async () => {
    const site = fakeSite();
    const realFetch = globalThis.fetch;
    globalThis.fetch = site.fetch;
    try {
      await seed(site, "page.privacy", `${FRONT}<!-- shared:analytics -->\n`);
      // The shared text changes after the page was written to the site.
      await testEnv.DB.prepare("UPDATE legal_sections SET body = ? WHERE key = ?").bind("Newer wording.", "analytics").run();
      const data = (await legalLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: new Request("https://carrel.test/p/de-info/legal") } as never)) as {
        pages: { type: string; setUp: boolean; behind?: boolean; shared?: string[] }[];
        canManage: boolean;
        sections: unknown[];
      };
      expect(data.pages.map((p) => [p.type, p.setUp])).toEqual([["privacy", true], ["terms", false]]);
      expect(data.pages[0]).toMatchObject({ behind: true, shared: ["analytics"] });
      expect(data.canManage).toBe(true);
      expect(data.sections).toHaveLength(2);
    } finally {
      globalThis.fetch = realFetch;
    }
  });

  it("changes a section only for the Owner, through the action", async () => {
    const body = new FormData();
    body.set("intent", "save-section");
    body.set("key", "hosting");
    body.set("title", "Hosting");
    body.set("body", "New text.");
    const request = () => new Request("https://carrel.test/p/de-info/legal", { method: "POST", body });
    const ok = await legalAction({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: request() } as never);
    expect(ok).toMatchObject({ saved: "hosting" });
    await expect(legalAction({ params: { project: SLUG }, context: await contextFor("editor@test.invalid"), request: request() } as never)).rejects.toMatchObject({ status: 403 });
  });
});

test/roles.test.ts.source:
// Planted problems for shared access: a person may do only what their role on a project allows,
// and sees nothing of a project not shared with them.

import { beforeEach, describe, expect, it } from "vitest";

import { findViewer, requireAction, visibleProjects, type Viewer } from "~/lib/people.server";
import { can } from "~/lib/roles";
import { addPerson, addProject, resetDb, share, testEnv } from "./env";

let owner: Viewer;
let reader: Viewer;
let editor: Viewer;
let outsider: Viewer;
let novel: number;
let series: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const readerId = await addPerson("reader@test.invalid");
  const editorId = await addPerson("editor@test.invalid");
  await addPerson("outsider@test.invalid");
  novel = await addProject("paluxy-portal");
  series = await addProject("blog-series");
  await share(novel, readerId, "reader");
  await share(novel, editorId, "editor");
  owner = (await findViewer(testEnv.DB, "owner@test.invalid"))!;
  reader = (await findViewer(testEnv.DB, "reader@test.invalid"))!;
  editor = (await findViewer(testEnv.DB, "editor@test.invalid"))!;
  outsider = (await findViewer(testEnv.DB, "outsider@test.invalid"))!;
});

async function status(viewer: Viewer, project: number, action: Parameters<typeof requireAction>[3]) {
  try {
    await requireAction(testEnv.DB, viewer, project, action);
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

describe("roles: refusals", () => {
  it("refuses a Reader who saves", async () => {
    expect(await status(reader, novel, "edit")).toBe(403);
  });

  it("refuses an Editor who publishes", async () => {
    expect(await status(editor, novel, "publish")).toBe(403);
  });

  it("refuses an Editor who sends externally or manages people", async () => {
    expect(await status(editor, novel, "send_external")).toBe(403);
    expect(await status(editor, novel, "manage")).toBe(403);
  });

  it("answers 404, not 403, when a non-member reads a project", async () => {
    expect(await status(outsider, novel, "read")).toBe(404);
  });

  it("answers 404 for a shared user on a project not shared with them", async () => {
    expect(await status(reader, series, "read")).toBe(404);
  });

  it("gives nobody a role from nothing", () => {
    expect(can(null, "read")).toBe(false);
  });
});

describe("roles: what is allowed", () => {
  it("lets a Reader read and comment", async () => {
    expect(await status(reader, novel, "read")).toBe(200);
    expect(await status(reader, novel, "comment")).toBe(200);
  });

  it("lets an Editor edit", async () => {
    expect(await status(editor, novel, "edit")).toBe(200);
  });

  it("lets the Owner do everything on every project, shared or not", async () => {
    for (const action of ["read", "comment", "edit", "publish", "send_external", "manage"] as const) {
      expect(await status(owner, series, action)).toBe(200);
    }
  });
});

describe("roles: what each person sees", () => {
  it("shows a shared user only the projects shared with them", async () => {
    expect((await visibleProjects(testEnv.DB, reader)).map((p) => p.slug)).toEqual(["paluxy-portal"]);
    expect(await visibleProjects(testEnv.DB, outsider)).toEqual([]);
  });

  it("shows the Owner every project", async () => {
    expect((await visibleProjects(testEnv.DB, owner)).map((p) => p.slug).sort()).toEqual(["blog-series", "paluxy-portal"]);
  });
});

describe("schema: the Owner cannot be granted twice", () => {
  it("refuses a second Owner row", async () => {
    await expect(addPerson("second@test.invalid", { owner: true })).rejects.toThrow();
  });

  it("refuses 'owner' as a membership role", async () => {
    const id = await addPerson("sneaky@test.invalid");
    await expect(
      testEnv.DB.prepare("INSERT INTO project_members (project_id, person_id, role) VALUES (?, ?, 'owner')")
        .bind(novel, id)
        .run(),
    ).rejects.toThrow();
  });
});

test/routes.test.ts.source:
// The editor's routes, driven through their loaders and actions with a real request context: the
// preview is private to each person and sandboxed, and a first publish asks before it acts.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as editorAction } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function contextFor(email: string, env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function preview(email: string, env: Env) {
  const context = await contextFor(email, env);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/preview`);
  try {
    return (await previewLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never)) as Response;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function post(email: string, env: Env, fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one`, { method: "POST", body });
  return editorAction({ request, params: { project: SLUG, item: "post-one" }, context: await contextFor(email, env) } as never);
}

async function seedPost(site: ReturnType<typeof fakeSite>) {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "seed" });
  return saved.version;
}

describe("the preview", () => {
  it("renders the viewer's own draft through the site, sandboxed and frameable by Carrel only", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "read");
    await autosave(env.DB, project, owner, "post-one", { source: "---\ntitle: Owner draft\n---\nNot on the site.\n", baseVersion: version });

    const response = await preview("owner@test.invalid", env);
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(response.headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
    const html = await response.text();
    expect(html).toContain("Owner draft");
    expect(html).toContain('<base href="https://site.test/">');
  });

  it("PLANT: never shows one person's working draft to another", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const editor = await viewerFor("editor@test.invalid");
    const project = await requireSiteProject(env.DB, editor, SLUG, "edit");
    await autosave(env.DB, project, editor, "post-one", { source: "---\ntitle: Editor secret\n---\nx\n", baseVersion: version });

    const html = await (await preview("reader@test.invalid", env)).text();
    expect(html).toContain("Site copy");
    expect(html).not.toContain("Editor secret");
  });

  it("PLANT: refuses a non-member with the same 404 as a missing project", async () => {
    vi.stubGlobal("fetch", fakeSite().fetch);
    expect((await preview("stranger@test.invalid", connectedEnv())).status).toBe(404);
  });

  it("explains a site that is not connected inside the frame instead of failing", async () => {
    const response = await preview("owner@test.invalid", testEnv);
    expect(response.status).toBe(200);
    expect(await response.text()).toContain("not connected");
  });
});

describe("publishing from the editor", () => {
  it("asks before a first publish, and publishes on the explicit second ask", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);

    const ask = await post("owner@test.invalid", env, { intent: "publish", expectedVersion: version, source: "---\ntitle: Site copy\n---\nOn the site.\n" });
    expect(ask).toEqual({ intent: "publish", needsConfirm: true });
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");

    const done = await post("owner@test.invalid", env, {
      intent: "publish",
      confirm: "first-publish",
      expectedVersion: version,
      source: "---\ntitle: Site copy\n---\nOn the site.\n",
    });
    expect(done).toMatchObject({ intent: "write", outcome: { ok: true, status: "published" } });
  });

  it("PLANT: refuses an Editor's publish from the editor, confirmed or not", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    await expect(
      post("editor@test.invalid", env, { intent: "publish", confirm: "first-publish", expectedVersion: version, source: "x" }),
    ).rejects.toSatisfy((thrown: unknown) => thrown instanceof Response && thrown.status === 403);
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");
  });
});

test/waiting.test.ts.source:
// Work waiting on a person that the site does not know yet: an AI draft for a new slug is listed in
// the project's Posts, opens in the editor and previews as the AI draft; an indexed post carries a
// count of AI drafts waiting. All of it private to the person the drafts belong to.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { requireSiteProject } from "~/lib/projects.server";
import { titleOf } from "~/lib/waiting.server";
import { loader as editorLoader } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraft(email: string, item: string, source: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source });
}

async function list(email: string, query = "") {
  const request = new Request(`https://carrel.test/p/${SLUG}${query}`);
  return (await projectLoader({ request, params: { project: SLUG }, context: await context(email) } as never)).items;
}

const NEW_POST = "---\ntitle: A desk apart\n---\nWords for a new post.\n";

describe("the project's Posts list", () => {
  it("lists an AI draft for a post the site does not have, and its editor opens", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "a-desk-apart", title: "A desk apart", status: "draft", isNew: true, aiDrafts: 1 });

    const page = await editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never);
    expect(page.source).toBe("");
    expect(page.aiDrafts).toHaveLength(1);
  });

  it("includes it under the Draft filter and the search, and leaves it out of Published and a kind", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid", "?status=draft")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=desk")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=elephant")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?status=published")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?kind=post")).toHaveLength(0);
  });

  it("lists a draft of the person's own for a new post too", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "edit");
    await autosave(env.DB, project, owner, "mine", { source: "---\ntitle: Mine\n---\nx\n", baseVersion: null });
    const items = await list("owner@test.invalid");
    expect(items[0]).toMatchObject({ itemId: "mine", title: "Mine", isNew: true, ownDraft: true, aiDrafts: 0 });
  });

  it("marks an indexed post that has AI drafts waiting, with the count", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    expect(saved.version).toBeTruthy();
    await refreshIndex(env, { id: projectId, site: "dustinedwards" });
    await aiDraft("owner@test.invalid", "post-one", "A better take.");
    await aiDraft("owner@test.invalid", "post-one", "Another take.");
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "post-one", isNew: false, aiDrafts: 2 });
  });

  it("PLANT: shows nobody else's AI drafts, and the editor of one still answers 404", async () => {
    await aiDraft("editor@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid")).toHaveLength(0);
    await expect(editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the preview of an AI-draft-only post", () => {
  it("renders the AI draft through the site, labelled as an AI draft", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const request = new Request(`https://carrel.test/p/${SLUG}/e/a-desk-apart/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)) as Response;
    const html = await response.text();
    expect(html).toContain("A desk apart");
    expect(html).toContain("AI draft from Claude. It is not your draft and it is not on the site.");
  });

  it("still says there is nothing to preview when there is no AI draft either", async () => {
    const request = new Request(`https://carrel.test/p/${SLUG}/e/none/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "none" }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(await response.text()).toContain("There is nothing to preview yet.");
  });
});

describe("titleOf", () => {
  it("reads a plain or quoted frontmatter title, and nothing when there is none", () => {
    expect(titleOf("---\ntitle: Plain\n---\nx")).toBe("Plain");
    expect(titleOf('---\ntitle: "Quoted: yes"\n---\nx')).toBe("Quoted: yes");
    expect(titleOf("No frontmatter\ntitle: nope")).toBe("");
  });
});

test/content.test.ts.source:
// Planted problems for writes to a site (design section 7, "Access, roles, key"): a Reader saves, an
// Editor publishes, an Editor changes a live post, a non-member reads, and a stale expectedVersion.
// Each must be refused, and refused before the site is asked to change anything.

import { beforeEach, describe, expect, it } from "vitest";

import { autosave, readDraft, writeToSite } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** A post already on the site, saved by the Owner, returned with its current version. */
async function seed(site: ReturnType<typeof fakeSite>, env: Env, status: "draft" | "published" = "draft") {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One\n", expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  if (status === "draft") return saved.version;
  const published = await writeToSite(env, project, viewer, "post-one", { action: "publish", expectedVersion: saved.version }, site.fetch);
  if (!published.ok) throw new Error(published.message);
  return published.version;
}

function writesTo(site: ReturnType<typeof fakeSite>) {
  return site.requests.filter((r) => !r.startsWith("GET"));
}

describe("PLANT: a non-member reads", () => {
  it("is answered 404, the same as a project that does not exist", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, "no-such-project", "read"))).toBe(404);
  });

  it("is answered 404 for a project that is not a site", async () => {
    await addProject("a-book");
    const owner = await viewerFor("owner@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, owner, "a-book", "read"))).toBe(404);
  });
});

describe("PLANT: a Reader saves", () => {
  it("is refused for autosave and for a save to the site, and the site hears nothing", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const { viewer, project } = await as("reader@test.invalid");
    expect(await refusal(autosave(env.DB, project, viewer, "post-one", { source: "x", baseVersion: null }))).toBe(403);
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }, site.fetch)),
    ).toBe(403);
    expect(site.requests).toEqual([]);
  });
});

describe("PLANT: an Editor publishes", () => {
  it("is refused for publish, schedule and unpublish before any request", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    for (const request of [
      { action: "publish" as const, expectedVersion: version },
      { action: "schedule" as const, expectedVersion: version, publishAt: "2030-01-01T00:00:00Z" },
      { action: "unpublish" as const, expectedVersion: version },
    ]) {
      expect(await refusal(writeToSite(env, project, viewer, "post-one", request, site.fetch)), request.action).toBe(403);
    }
    expect(site.requests).toEqual([]);
  });

  it("is refused when the change would alter a live post, since that is a publish", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env, "published");
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Changed live\n", expectedVersion: version }, site.fetch)),
    ).toBe(403);
    expect(writesTo(site)).toEqual([]);
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One\n");
  });

  it("lets an Editor save a draft, and records who did it", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("editor@test.invalid");
    const outcome = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One, edited\n", expectedVersion: version }, site.fetch);
    expect(outcome).toMatchObject({ ok: true, status: "draft" });
    const change = await testEnv.DB.prepare("SELECT person_id, action, version_before FROM changes WHERE id = ?")
      .bind(outcome.ok ? outcome.changeId : "")
      .first();
    expect(change).toEqual({ person_id: viewer.id, action: "save", version_before: version });
  });
});

describe("PLANT: a stale expectedVersion", () => {
  it("is refused by the site, reported as a conflict, and the person's draft is kept", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    // Someone else moves the post on.
    const moved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Moved\n", expectedVersion: version }, site.fetch);
    expect(moved.ok).toBe(true);

    await autosave(env.DB, project, viewer, "post-one", { source: "# My edit\n", baseVersion: version });
    const stale = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# My edit\n", expectedVersion: version }, site.fetch);
    expect(stale).toMatchObject({ ok: false, reason: "conflict" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# Moved\n");
    expect((await readDraft(env.DB, project, viewer, "post-one"))?.source).toBe("# My edit\n");
  });

  it("refuses a create over a slug the site already holds", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    const clobber = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Clobber\n", expectedVersion: null }, site.fetch);
    expect(clobber).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("the Owner's writes", () => {
  it("publish, index the result, record the change, and clear the draft that was sent", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    await autosave(env.DB, project, viewer, "post-one", { source: "# One, final\n", baseVersion: version });
    const outcome = await writeToSite(
      env,
      project,
      viewer,
      "post-one",
      { action: "publish", expectedVersion: version, source: "# One, final\n" },
      site.fetch,
    );
    expect(outcome).toMatchObject({ ok: true, status: "published" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One, final\n");
    expect(await readDraft(env.DB, project, viewer, "post-one")).toBeNull();
    const indexed = await testEnv.DB.prepare("SELECT status, title FROM site_items WHERE project_id = ? AND item_id = ?")
      .bind(projectId, "post-one")
      .first();
    expect(indexed).toEqual({ status: "published", title: "One, final" });
    const count = await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>();
    expect(count!.n).toBe(2);
  });

  it("reports a site that is not connected rather than failing obscurely", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    await expect(
      writeToSite(testEnv, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }),
    ).rejects.toThrow(/No SITE_DUSTINEDWARDS_KEY set/);
  });
});

test/agent-keys.test.ts.source:
// Named agent keys at the AI door (job_77fd33040bdd). An agent that cannot complete OAuth (Grok Build)
// presents a key, and the key's Worker secret NAME is the agent: AGENT_KEY_GROK is "grok". The key
// says who is knocking and grants nothing: the agent is the person row "agent:grok" in People, its
// role comes from there, and it is credited as "agent:grok", never as Dustin. Every refusal below
// must end with nothing written, and each is planted in scripts/plant-gates.mjs or by hand (see the
// PR) and must turn the named test red.

import { createExecutionContext } from "cloudflare:test";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { agentPrincipal, keysMatch } from "~/lib/agent-keys.server";
import { addAgent, listPeople, PeopleRefusal, setProjectRole } from "~/lib/people-admin.server";
import { findAgentViewer } from "~/lib/people.server";
import { aiDoor } from "~/lib/mcp/door";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { MCP_HOST, modernRequest, readMessage, type ToolCallResult } from "./mcp-client";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const KEY = "grok-test-key-0123456789abcdefghijklmnop";
const OTHER_KEY = "other-test-key-0123456789abcdefghijklmnop";
const SLUG = "de-info";
const UNSHARED = "other-site";

let site: ReturnType<typeof fakeSite>;
let agentId: number;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  agentId = await addPerson("agent:grok");
  projectId = await addProject(SLUG, "dustinedwards");
  await addProject(UNSHARED, "foxing");
  await share(projectId, agentId, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
});

afterEach(() => vi.unstubAllGlobals());

const env = (extra: Record<string, string> = {}): Env => connectedEnv({ AGENT_KEY_GROK: KEY, ...extra });

async function door(request: Request, e: Env = env()) {
  return aiDoor(request, e, createExecutionContext());
}

function authed(authorization: string | null, name: string, args: Record<string, unknown> = {}, headers: Record<string, string> = {}) {
  return modernRequest(3, "tools/call", { name, arguments: args }, { ...(authorization ? { Authorization: authorization } : {}), ...headers });
}

async function call(name: string, args: Record<string, unknown> = {}, opts: { key?: string; env?: Env; headers?: Record<string, string> } = {}) {
  const response = await door(authed(`Bearer ${opts.key ?? KEY}`, name, args, opts.headers), opts.env);
  if (response.status !== 200) return { status: response.status, result: undefined as ToolCallResult | undefined };
  return { status: 200, result: (await readMessage(response)).result as unknown as ToolCallResult };
}

async function seedPost() {
  return (await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nDustin's words.\n", expectedVersion: null, changeId: "seed" })).version;
}

const rows = async (sql: string) => (await testEnv.DB.prepare(sql).all()).results;

describe("what a named agent key does", () => {
  it("lets the agent read, save an AI draft beside Dustin's, flag and preview, credited as agent:grok", async () => {
    await seedPost();
    const listed = await call("list_projects");
    expect(listed.result!.structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "editor" }] });
    expect(((listed.result!.structuredContent as { projects: unknown[] }).projects).length).toBe(1);

    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "---\ntitle: Post one\n---\nGrok's try.\n", note: "A try." });
    expect(saved.result!.isError).toBeUndefined();
    expect(await rows("SELECT client, source FROM ai_drafts")).toEqual([{ client: "agent:grok", source: "---\ntitle: Post one\n---\nGrok's try.\n" }]);
    const owner = await viewerFor("owner@test.invalid");
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${owner.id}`)).toEqual([]);
    expect(await rows(`SELECT person_id FROM ai_drafts WHERE person_id = ${agentId}`)).toHaveLength(1);

    const flagged = await call("add_finding", { project: SLUG, item: "post-one", message: "A flag." });
    expect(flagged.result!.structuredContent).toMatchObject({ flagged: true });
    expect(await rows("SELECT message FROM findings")).toEqual([{ message: "A flag. (from agent:grok)" }]);

    const preview = await call("preview", { project: SLUG, item: "post-one" });
    expect(preview.result!.isError).toBeUndefined();

    // Nothing reached the site's record: an agent's saved draft lives only in Carrel, and nothing is credited to Dustin.
    expect(await rows("SELECT id FROM changes")).toEqual([]);
    expect(site.requests.filter((r) => (r.startsWith("POST") || r.startsWith("PUT")) && !r.endsWith("/preview"))).toEqual([]);
  });

  it("PLANT: a key trying publish is refused with the Owner-only message, and nothing is published", async () => {
    const version = await seedPost();
    const { result } = await call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Only the Owner's own sessions may publish." }] });
    expect((await site.adapter.content.get("post-one"))!.status).not.toBe("published");
    expect(await rows("SELECT * FROM ai_publications")).toEqual([]);
    expect(await rows("SELECT id FROM changes")).toEqual([]);
  });

  it("PLANT: the role is the person's role in People, never the key's: a Reader agent cannot save a draft", async () => {
    await seedPost();
    await testEnv.DB.prepare("UPDATE project_members SET role = 'reader' WHERE person_id = ?").bind(agentId).run();
    const { result } = await call("save_draft", { project: SLUG, item: "post-one", source: "x" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "You may not write drafts on this project." }] });
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: a project the agent has no role on is not there for it: not listed, not read, not drafted, not flagged", async () => {
    const { result: listed } = await call("list_projects");
    expect(JSON.stringify(listed!.structuredContent)).not.toContain(UNSHARED);
    for (const [name, args] of [
      ["search_items", {}],
      ["read_item", { item: "post-one" }],
      ["save_draft", { item: "post-one", source: "x" }],
      ["add_finding", { item: "post-one", message: "m" }],
      ["publish", { item: "post-one", expected_version: "v" }],
    ] as const) {
      const { result } = await call(name, { project: UNSHARED, ...args });
      expect(result, name).toMatchObject({ isError: true, content: [{ text: "Not found, or not shared with this person." }] });
    }
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
    expect(await rows("SELECT id FROM findings")).toEqual([]);
  });

  it("PLANT: a row marked Owner is never an agent: the key is refused", async () => {
    // The database allows one Owner, so the real one has to go before the agent's row can be flagged.
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'owner@test.invalid'").run();
    await testEnv.DB.prepare("UPDATE people SET is_owner = 1 WHERE email = 'agent:grok'").run();
    expect(await findAgentViewer(testEnv.DB, "grok")).toBeNull();
    expect((await call("list_projects")).status).toBe(403);
  });
});

describe("what a named agent key refuses", () => {
  it("PLANT: an unknown key is refused by the OAuth path: 401 with the Bearer challenge, nothing run", async () => {
    const response = await door(authed(`Bearer ${OTHER_KEY}`, "list_projects"));
    expect(response.status).toBe(401);
    expect(response.headers.get("WWW-Authenticate")).toContain("resource_metadata=");
    const near = await door(authed(`Bearer ${KEY}x`, "list_projects"));
    expect(near.status).toBe(401);
    const short = await door(authed(`Bearer ${KEY.slice(0, -1)}`, "list_projects"));
    expect(short.status).toBe(401);
  });

  it("PLANT: a key whose secret is absent is refused, and so is one that was revoked by deleting the secret", async () => {
    const without = connectedEnv();
    expect((await call("list_projects", {}, { env: without })).status).toBe(401);
    const revoked: Env = { ...env() };
    delete revoked.AGENT_KEY_GROK;
    expect((await call("list_projects", {}, { env: revoked })).status).toBe(401);
    // A blank secret admits nobody, and is not a key that matches the empty string.
    expect((await call("list_projects", {}, { env: env({ AGENT_KEY_GROK: "  " }), key: " " })).status).toBe(401);
  });

  it("PLANT: a key whose person row is disabled, or missing, is refused at once, and never falls through to OAuth", async () => {
    expect((await call("list_projects")).status).toBe(200);
    await testEnv.DB.prepare("UPDATE people SET disabled_at = '2026-10-07T00:00:00Z' WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    await testEnv.DB.prepare("DELETE FROM project_members").run();
    await testEnv.DB.prepare("DELETE FROM people WHERE email = 'agent:grok'").run();
    expect((await call("list_projects")).status).toBe(403);
    expect(await rows("SELECT id FROM ai_drafts")).toEqual([]);
  });

  it("PLANT: the agent's name is the secret's name, never the request's: a header or body naming another agent changes nothing", async () => {
    await addPerson("agent:other");
    await share(projectId, (await viewerFor("agent:other")).id, "editor");
    await seedPost();
    const claims = {
      "X-Agent": "other",
      "X-Agent-Name": "other",
      "X-Carrel-Agent": "agent:other",
      "X-Forwarded-User": "owner@test.invalid",
      "Cf-Access-Authenticated-User-Email": "owner@test.invalid",
      "Cf-Access-Jwt-Assertion": "x.y.z",
      "Mcp-Client": "agent:other",
    };
    const saved = await call("save_draft", { project: SLUG, item: "post-one", source: "x" }, { headers: claims });
    expect(saved.result!.isError).toBeUndefined();
    // A body that claims an identity is refused by the tool's own schema; nothing is written.
    for (const claim of [{ agent: "other" }, { client: "agent:other" }, { person: "owner@test.invalid" }]) {
      const refused = await door(authed(`Bearer ${KEY}`, "save_draft", { project: SLUG, item: "post-one", source: "y", ...claim }, claims));
      expect(JSON.stringify(await readMessage(refused)), JSON.stringify(claim)).toMatch(/error|invalid|unrecognized|additional/i);
    }
    expect(await rows("SELECT client FROM ai_drafts")).toEqual([{ client: "agent:grok" }]);
    // Two agents with two keys: each key is its own name, whichever the request claims to be.
    const second = await call("save_draft", { project: SLUG, item: "post-one", source: "z" }, { env: env({ AGENT_KEY_OTHER: OTHER_KEY }), key: OTHER_KEY, headers: { "X-Agent-Name": "grok" } });
    expect(second.result!.isError).toBeUndefined();
    expect((await rows("SELECT client FROM ai_drafts ORDER BY id")).map((r) => r.client)).toEqual(["agent:grok", "agent:other"]);
  });

  it("PLANT: a malformed Authorization header is never an agent: it goes to the OAuth path and is refused there", async () => {
    for (const header of [`Basic ${KEY}`, "Bearer", "Bearer ", `Bearer ${KEY} extra`, `Token ${KEY}`, KEY, `Bearer\t${KEY}`, ""]) {
      expect((await door(authed(header || null, "list_projects"))).status, header).toBe(401);
    }
    // The scheme is case-insensitive, as HTTP's is.
    expect((await door(authed(`bearer ${KEY}`, "list_projects"))).status).toBe(200);
  });

  it("is inert until a secret exists: with none, the door answers as it did before", async () => {
    const none = connectedEnv();
    expect(await agentPrincipal(none, `Bearer ${KEY}`)).toBeNull();
    const response = await door(modernRequest(1, "tools/list"), none);
    expect(response.status).toBe(401);
  });

  it("keeps the agent key to /mcp: another path on the door is never an agent's", async () => {
    for (const path of ["/", "/p/de-info", "/authorize", "/token", "/health"]) {
      const response = await door(new Request(`https://${MCP_HOST}${path}`, { headers: { Authorization: `Bearer ${KEY}` } }));
      if (path !== "/health") expect(response.status, path).toBeGreaterThanOrEqual(400);
      expect(await response.text(), path).not.toContain("projects");
    }
  });
});

describe("how the key is read", () => {
  it("names the agent from the secret's name, lower-cased, and only a valid name", async () => {
    expect(await agentPrincipal({ AGENT_KEY_GROK: KEY }, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal({ AGENT_KEY_Mixed_Case: KEY }, `Bearer ${KEY}`)).toBe("mixed_case");
    for (const name of ["AGENT_KEY_", "AGENT_KEY_has space", "AGENT_KEY_" + "x".repeat(33), "AGENT_KEY_-lead", "NOT_AGENT_KEY_GROK", "agent_key_grok"]) {
      expect(await agentPrincipal({ [name]: KEY }, `Bearer ${KEY}`), name).toBeNull();
    }
    expect(await agentPrincipal({ AGENT_KEY_GROK: 7 as unknown as string }, `Bearer 7`)).toBeNull();
  });

  it("picks the right agent among several and refuses a key that is none of them", async () => {
    const e = { AGENT_KEY_GROK: KEY, AGENT_KEY_OTHER: OTHER_KEY };
    expect(await agentPrincipal(e, `Bearer ${OTHER_KEY}`)).toBe("other");
    expect(await agentPrincipal(e, `Bearer ${KEY}`)).toBe("grok");
    expect(await agentPrincipal(e, "Bearer nope")).toBeNull();
    expect(await agentPrincipal(e, null)).toBeNull();
  });

  it("compares digests: equal keys match, and any difference in content or length does not", async () => {
    expect(await keysMatch(KEY, KEY)).toBe(true);
    expect(await keysMatch(KEY, `${KEY}x`)).toBe(false);
    expect(await keysMatch(KEY, KEY.slice(1))).toBe(false);
    expect(await keysMatch(KEY, OTHER_KEY)).toBe(false);
    expect(await keysMatch("", KEY)).toBe(false);
  });
});

describe("adding an agent in People", () => {
  it("is the Owner's alone, and the agent row is never an Owner or a reviewer, with no role until one is set", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const added = await addAgent(testEnv.DB, owner, { name: " Claude-Two ", label: "Claude Two" });
    expect(added).toMatchObject({ email: "agent:claude-two", name: "Claude Two", isOwner: false, isReviewer: false, roles: [] });
    expect(await findAgentViewer(testEnv.DB, "claude-two")).toMatchObject({ email: "agent:claude-two" });

    const editor = await addPerson("editor@test.invalid");
    await share(projectId, editor, "editor");
    await expect(addAgent(testEnv.DB, await viewerFor("editor@test.invalid"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    await expect(addAgent(testEnv.DB, await viewerFor("agent:grok"), { name: "sneaky" })).rejects.toMatchObject({ status: 404 });
    expect(await rows("SELECT email FROM people WHERE email = 'agent:sneaky'")).toEqual([]);
  });

  it("refuses a duplicate and a name that is not a name, and changes nothing", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const before = await rows("SELECT email FROM people");
    for (const name of ["grok", "GROK", "", "a b", "a@b.co", "-x", "x".repeat(33), "agent:x"]) {
      await expect(addAgent(testEnv.DB, owner, { name }), name).rejects.toBeInstanceOf(PeopleRefusal);
    }
    expect(await rows("SELECT email FROM people")).toEqual(before);
  });

  it("lists the agent and lets the Owner set its role like anyone's, Editor allowed", async () => {
    const owner = await viewerFor("owner@test.invalid");
    await addAgent(testEnv.DB, owner, { name: "fresh" });
    const fresh = (await viewerFor("agent:fresh")).id;
    await setProjectRole(testEnv.DB, owner, fresh, projectId, "editor");
    const { people } = await listPeople(testEnv.DB, owner);
    expect(people.find((p) => p.email === "agent:fresh")!.roles).toEqual([{ projectId, role: "editor" }]);
  });
});

test/csp.test.ts.source:
// The Content Security Policy, required before the editor ships: every page carries a per-request
// nonce policy with no unsafe script source, the preview alone may be framed and only by Carrel, and
// the site's page inside it runs sandboxed.

import { createLocalJWKSet, exportJWK, generateKeyPair, SignJWT, type JWK } from "jose";
import { beforeAll, beforeEach, describe, expect, it } from "vitest";

import { previewPolicy, previewResponse, withSiteBase } from "~/lib/preview.server";

import { appPolicy, newNonce, withPolicy } from "../workers/csp";
import { gate } from "../workers/gate";

import { addPerson, resetDb, testEnv } from "./env";

describe("the app policy", () => {
  it("allows scripts only by this render's nonce, never inline or eval", () => {
    const policy = appPolicy("abc123");
    const scripts = policy.split("; ").find((d) => d.startsWith("script-src "))!;
    expect(scripts).toBe("script-src 'nonce-abc123' 'strict-dynamic'");
    expect(policy).not.toMatch(/'unsafe-eval'/);
    expect(policy).toContain("object-src 'none'");
    expect(policy).toContain("base-uri 'none'");
    expect(policy).toContain("frame-ancestors 'none'");
    expect(policy).toContain("frame-src 'self'");
  });

  it("stays strict for Cloudflare's Web Analytics beacon: no host in script-src, connect-src is 'self'", () => {
    const directives = appPolicy("abc123").split("; ");
    const scripts = directives.find((d) => d.startsWith("script-src "))!;
    const connect = directives.find((d) => d.startsWith("connect-src "))!;
    const why =
      "Carrel is private and its hosts are excluded from Web Analytics in the Cloudflare dashboard; do not loosen the policy for the beacon (static.cloudflareinsights.com).";
    // Only the nonce and 'strict-dynamic' may appear: no scheme, no host, no wildcard.
    expect(scripts.split(" ").slice(1), why).toEqual(["'nonce-abc123'", "'strict-dynamic'"]);
    expect(connect, why).toBe("connect-src 'self'");
  });

  it("mints a different nonce every time", () => {
    const nonces = new Set(Array.from({ length: 50 }, newNonce));
    expect(nonces.size).toBe(50);
  });

  it("PLANT: a page without a policy gets one; a route's own policy is kept", () => {
    const page = withPolicy(new Response("<html></html>"), "n1");
    expect(page.headers.get("Content-Security-Policy")).toBe(appPolicy("n1"));
    const preview = withPolicy(previewResponse("<html><head></head></html>", "https://site.test"), "n1");
    expect(preview.headers.get("Content-Security-Policy")).toBe(previewPolicy("https://site.test"));
  });

  it("adds the policy to a response whose headers are immutable", () => {
    const redirect = Response.redirect("https://carrel.test/", 302);
    expect(withPolicy(redirect, "n2").headers.get("Content-Security-Policy")).toBe(appPolicy("n2"));
  });
});

describe("the preview", () => {
  it("runs the site's page sandboxed: no script, no forms, only the site's styles and images", () => {
    const policy = previewPolicy("https://site.test");
    expect(policy.split("; ")[0]).toBe("sandbox");
    expect(policy).toContain("default-src 'none'");
    expect(policy).toContain("script-src 'none'");
    expect(policy).toContain("form-action 'none'");
    expect(policy).toContain("style-src https://site.test 'unsafe-inline'");
    expect(policy).toContain("frame-ancestors 'self'");
  });

  it("resolves the page's relative URLs against the site and drops the page's own <base>", () => {
    const html = withSiteBase('<html><head lang="en"><base href="https://evil.test/"><link href="/a.css"></head></html>', "https://site.test");
    expect(html).toBe('<html><head lang="en"><base href="https://site.test/"><link href="/a.css"></head></html>');
    expect(withSiteBase("<p>no head</p>", "https://site.test")).toBe('<base href="https://site.test/"><p>no head</p>');
  });
});

describe("framing through the gate", () => {
  let keys: ReturnType<typeof createLocalJWKSet>;
  let token: string;

  beforeAll(async () => {
    const pair = await generateKeyPair("RS256", { extractable: true });
    const jwk: JWK = { ...(await exportJWK(pair.publicKey)), kid: "test", alg: "RS256" };
    keys = createLocalJWKSet({ keys: [jwk] });
    token = await new SignJWT({ email: "owner@test.invalid" })
      .setProtectedHeader({ alg: "RS256", kid: "test" })
      .setIssuer(testEnv.ACCESS_TEAM_DOMAIN)
      .setAudience(testEnv.ACCESS_AUD)
      .setIssuedAt()
      .setExpirationTime("5m")
      .sign(pair.privateKey);
  });

  beforeEach(async () => {
    await resetDb();
    await addPerson("owner@test.invalid", { owner: true });
  });

  /** A verified Owner's request, so the test reads only what the gate does to the rendered response. */
  function through(render: () => Response) {
    const request = new Request("https://carrel.test/", { headers: { "Cf-Access-Jwt-Assertion": token } });
    return gate(request, testEnv, async () => render(), keys);
  }

  it("PLANT: denies framing of every page by default", async () => {
    const response = await through(() => new Response("page"));
    expect(response.headers.get("X-Frame-Options")).toBe("DENY");
  });

  it("lets the preview be framed by Carrel alone", async () => {
    const response = await through(() => previewResponse("<html><head></head></html>", "https://site.test"));
    expect(response.headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
  });

  it("cannot be loosened by a route asking for ALLOW-FROM or anything else", async () => {
    const response = await through(() => new Response("page", { headers: { "X-Frame-Options": "ALLOW-FROM https://evil.test" } }));
    expect(response.headers.get("X-Frame-Options")).toBe("DENY");
  });
});

test/ai-routes.test.ts.source:
// The browser's side of AI work: the unpublish page the email links to, the AI draft page, and
// flags in the editor. Driven through loaders and actions with a real request context.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { addFinding, saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as aiDraftAction, loader as aiDraftLoader } from "~/routes/ai-draft";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { action as unpublishAction, loader as unpublishLoader } from "~/routes/unpublish";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  // The routes call the site through the global fetch, as the Worker does.
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function published() {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nWords.\n", expectedVersion: null, changeId: "s" });
  await site.adapter.content.publish("post-one", { expectedVersion: saved.version, changeId: "p" });
}

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

describe("the unpublish page", () => {
  it("opens without changing anything, and one button returns the post to draft", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    const page = (await unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof unpublishLoader>
    >;
    expect(page.item).toMatchObject({ title: "Post one", status: "published" });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");

    const done = await unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never);
    expect(done).toMatchObject({ ok: true, message: "Returned to draft. It is off the site." });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("PLANT: an Editor cannot open it or use it", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    expect(((await settle(unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(403);
    expect(
      ((await settle(unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("editor@test.invalid") } as never))) as Response).status,
    ).toBe(403);
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");
  });
});

describe("AI drafts in the browser", () => {
  it("shows an AI draft to the person whose session saved it, and Use as my draft replaces only their working copy", async () => {
    await published();
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude 1.0" }, "post-one", { source: "AI text.", note: "A note." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    const page = (await aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof aiDraftLoader>>;
    expect(page.draft).toMatchObject({ client: "Claude 1.0", note: "A note.", source: "AI text." });

    const used = (await aiDraftAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never)) as Response;
    expect(used.headers.get("Location")).toBe(`/p/${SLUG}/e/post-one`);
    expect((await readDraft(testEnv.DB, project, viewer, "post-one"))?.source).toBe("AI text.");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nWords.\n");
  });

  it("PLANT: another person cannot see someone's AI draft", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude" }, "post-one", { source: "Private." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    expect(((await settle(aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
  });
});

describe("flags in the editor", () => {
  it("lists flags, and only the Owner dismisses one", async () => {
    await published();
    const reviewer = await viewerFor("owner@test.invalid");
    const { project } = await as("owner@test.invalid");
    const flag = await addFinding(testEnv.DB, project, { viewer: { ...reviewer, isReviewer: true }, client: "Grok Build" }, "post-one", { message: "Check this." });
    const params = { project: SLUG, item: "post-one" };
    const data = (await editorLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(data.flags).toMatchObject([{ status: "open", message: "Check this. (from Grok Build)" }]);

    const dismiss = (email: string) => {
      const body = new FormData();
      body.set("intent", "dismiss-flag");
      body.set("flag", String(flag.id));
      return context(email).then((c) => settle(editorAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context: c } as never)));
    };
    expect(((await dismiss("editor@test.invalid")) as Response).status).toBe(403);
    expect(await dismiss("owner@test.invalid")).toEqual({ intent: "dismiss-flag", dismissed: flag.id });
  });
});

test/editor-ux.test.ts.source:
// The editor and AI draft screens' behaviour behind the UX pass: "Use as my draft" writes the
// person's working copy in Carrel and nothing to the site, the AI draft's rendered view is private
// to its owner, and the save line says a draft on the site is not live.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { siteState } from "~/lib/save-state";
import { action as aiDraftAction } from "~/routes/ai-draft";
import { loader as aiPreviewLoader } from "~/routes/ai-draft.preview";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const THEIR_SOURCE = "---\ntitle: The AI's take\nunknown_key: kept\n---\nAn alternative opening.\n";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraftFor(email: string, item: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  const { id } = await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source: THEIR_SOURCE });
  return { id, viewer, project };
}

describe("Use as my draft", () => {
  it("writes the working copy in Carrel exactly as the AI wrote it, and sends nothing to the site", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    const { id, viewer, project } = await aiDraftFor("owner@test.invalid", "post-one");
    const before = site.requests.length;

    const result = await aiDraftAction({ params: { project: SLUG, item: "post-one", id: String(id) }, request: new Request("https://carrel.test/", { method: "POST" }), context: await context("owner@test.invalid") } as never);
    expect((result as Response).status).toBe(302);

    expect(await readDraft(env.DB, project, viewer, "post-one")).toMatchObject({ source: THEIR_SOURCE });
    expect(site.requests.slice(before).filter((r) => !r.startsWith("GET "))).toEqual([]);
    const onSite = await site.adapter.content.get("post-one");
    expect(onSite?.version).toBe(saved.version);
    expect(onSite?.source).toContain("On the site.");
  });
});

describe("the AI draft's rendered view", () => {
  it("renders the draft through the site for its owner", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    const response = (await aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(await response.text()).toContain("The AI's take");
  });

  it("PLANT: is never shown to another person, whose request answers 404", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    await expect(aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the save line", () => {
  it("does not read as live for a draft on the site", () => {
    expect(siteState("draft", false)).toBe("Saved as a draft on the site. Not published yet.");
    expect(siteState("draft", true)).toBe("Matches the site's draft. It is not live.");
    expect(siteState("scheduled", true)).toMatch(/scheduled/);
    expect(siteState("published", true)).toBe("Matches the live post");
  });
});

test/social.test.ts.source:
// The social queue (design decision 5) against fake Bluesky, X and routine endpoints. Planted: a reply
// attempt refused; a post failing the lint held; the template used only after the routine fails; the
// health email when a template post goes out. Nothing here reaches a real platform.

import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";
import { lintPost } from "~/lib/social/lint";
import { assertOriginalPost, clearBlueskySessions, oauthSignature, percentEncode, SocialRefused } from "~/lib/social/platforms.server";
import {
  BATCH_DELAY_MS,
  createAccount,
  decidePost,
  draftSocialPost,
  processSocial,
  recordPublication,
  ROUTINE_WAIT_MS,
  setSwitches,
  socialOverview,
} from "~/lib/social/queue.server";

import { addPerson, addProject, resetDb, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const ROUTINE_URL = "https://api.anthropic.com/v1/claude_code/routines/trig_01TEST/fire";

type Sent = { url: string; body: Record<string, unknown>; auth: string | null };

/** Bluesky, X and the routine trigger, answering as the real ones do. */
function fakeWorld(routineStatus: number | (() => number) = 200) {
  const sent: Sent[] = [];
  const fires: { text: string; headers: Record<string, string> }[] = [];
  const fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    const body = (await request.json().catch(() => ({}))) as Record<string, unknown>;
    if (request.url === ROUTINE_URL) {
      fires.push({ text: String(body.text ?? ""), headers: Object.fromEntries(request.headers) });
      const status = typeof routineStatus === "function" ? routineStatus() : routineStatus;
      if (status !== 200) return Response.json({ type: "error", error: { type: status === 429 ? "rate_limit_error" : "authentication_error", message: "no" } }, { status });
      return Response.json({ type: "routine_fire", claude_code_session_id: "session_01", claude_code_session_url: "https://claude.ai/code/session_01" });
    }
    sent.push({ url: request.url, body, auth: request.headers.get("Authorization") });
    if (request.url.endsWith("createSession")) return Response.json({ accessJwt: "jwt", did: "did:plc:test" });
    if (request.url.endsWith("createRecord")) return Response.json({ uri: `at://did:plc:test/app.bsky.feed.post/${sent.length}` });
    if (request.url === "https://api.x.com/2/tweets") return Response.json({ data: { id: `x${sent.length}`, text: body.text } });
    throw new Error(`the tests reach only the fakes, not ${request.url}`);
  }) as typeof globalThis.fetch;
  return { fetch, sent, fires };
}

let projectId: number;
let env: Env;
const NOW = new Date("2026-09-27T15:00:00Z");
const later = (ms: number) => new Date(NOW.getTime() + ms);

function mailbox() {
  const sent: { subject: string; text: string }[] = [];
  return { sent, EMAIL: { send: async (m: { subject: string; text: string }) => (sent.push(m), { messageId: "m" }) } as unknown as SendEmail };
}

async function owner() {
  return viewerFor("owner@test.invalid");
}

async function account(key: string, opts: { platform?: "bluesky" | "x"; kind?: "brand" | "personal"; mode?: "auto" | "approval"; budget?: number } = {}) {
  const o = await owner();
  const created = await createAccount(testEnv.DB, o, { key, name: key, platform: opts.platform ?? "bluesky", kind: opts.kind ?? "brand", handle: `${key}.bsky.social`, projectId });
  if (!created.ok) throw new Error(created.error);
  const row = await testEnv.DB.prepare("SELECT id FROM social_accounts WHERE key = ?").bind(key).first<{ id: number }>();
  await setSwitches(testEnv.DB, o, row!.id, { enabled: true, mode: opts.mode ?? "auto", monthlyBudgetMills: opts.budget ?? 0 });
  return row!.id;
}

async function posts() {
  return (await socialOverview(testEnv.DB, await owner())).posts.map((p) => ({ ...p.post, accountKey: p.accountKey }));
}

const PIECE = { id: "post-one", title: "Stromatolites of the Paluxy", url: "https://site.test/blog/post-one", summary: "What the river keeps." };

beforeEach(async () => {
  clearBlueskySessions();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  projectId = await addProject("germomics", "dustinedwards");
  env = {
    ...connectedEnv(),
    SOCIAL_ROUTINE_URL: ROUTINE_URL,
    SOCIAL_ROUTINE_TOKEN: "sk-ant-oat01-test",
    SOCIAL_GERMOMICS_BLUESKY_BLUESKY_APP_PASSWORD: "app-pass",
    SOCIAL_FOXING_BLUESKY_BLUESKY_APP_PASSWORD: "app-pass-2",
    SOCIAL_DUSTIN_X_X_API_KEY: "k",
    SOCIAL_DUSTIN_X_X_API_SECRET: "s",
    SOCIAL_DUSTIN_X_X_ACCESS_TOKEN: "t",
    SOCIAL_DUSTIN_X_X_ACCESS_SECRET: "ts",
  } as Env;
});

describe("PLANT: a reply attempt is refused, before anything is sent", () => {
  it("refuses a Bluesky record with a reply, a follow, a like, and any other endpoint", () => {
    const bsky = "https://bsky.social/xrpc/com.atproto.repo.createRecord";
    const reply = { uri: "at://x", cid: "y" };
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.feed.post", record: { $type: "app.bsky.feed.post", text: "hi", reply: { root: reply, parent: reply } } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.graph.follow", record: { $type: "app.bsky.graph.follow" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.feed.like", record: { $type: "app.bsky.feed.like" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.bsky.chat/xrpc/chat.bsky.convo.sendMessage", {})).toThrow(SocialRefused);
    expect(() => assertOriginalPost("GET", "https://bsky.social/xrpc/app.bsky.feed.searchPosts?q=x", undefined)).toThrow(SocialRefused);
  });

  it("refuses an X post that replies or quotes, and any other X endpoint", () => {
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi", reply: { in_reply_to_tweet_id: "1" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi", quote_tweet_id: "1" })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/dm_conversations/with/1/messages", { text: "hi" })).toThrow(SocialRefused);
  });

  it("lets an original post through", () => {
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi" })).not.toThrow();
    expect(() => assertOriginalPost("POST", "https://bsky.social/xrpc/com.atproto.repo.createRecord", { repo: "d", collection: "app.bsky.feed.post", record: { $type: "app.bsky.feed.post", text: "hi" } })).not.toThrow();
  });
});

describe("X signing", () => {
  it("matches the OAuth 1.0a signature in X's own documentation", async () => {
    // developer.x.com, "Creating a signature": the published example and its expected result.
    const params = {
      include_entities: "true",
      oauth_consumer_key: "xvz1evFS4wEEPTGEFPHBog",
      oauth_nonce: "kYjzVBB8Y0ZFabxSWbWovY3uYSQ2pTgmZeNu2VS4cg",
      oauth_signature_method: "HMAC-SHA1",
      oauth_timestamp: "1318622958",
      oauth_token: "370773112-GmHxMAgYyLbNEtIKZeRNFsMKPR9EyMZeS9weJAEb",
      oauth_version: "1.0",
      status: "Hello Ladies + Gentlemen, a signed OAuth request!",
    };
    expect(await oauthSignature("POST", "https://api.twitter.com/1.1/statuses/update.json", params, "kAcSOqF21Fu85e7zjz7ZN2U4ZRhfV3WpwPAoE3Z7kBw", "LswwdoUaIvS8ltyTt5jkRh4J50vUPVVHtR2YPi5kE")).toBe(
      "hCtSmYh+iHYCEqBWrE7C7hYmtUk=",
    );
    expect(percentEncode("Ladies + Gentlemen!*'()")).toBe("Ladies%20%2B%20Gentlemen%21%2A%27%28%29");
  });
});

describe("the primary path: a draft stored ahead", () => {
  it("sends the pre-drafted post when the piece goes live, with no routine and no AI", async () => {
    await account("germomics-bluesky");
    const world = fakeWorld();
    expect(await draftSocialPost(testEnv.DB, { accountKey: "germomics-bluesky", projectId, itemId: "post-one", text: `New episode: Stromatolites. ${PIECE.url}`, createdBy: "Claude 1.0" })).toMatchObject({ ok: true });

    // Before it goes live, nothing moves.
    expect((await processSocial(env, { fetcher: world.fetch, now: NOW })).sent).toBe(0);
    await recordPublication(testEnv.DB, projectId, PIECE, NOW);
    const tick = await processSocial(env, { fetcher: world.fetch, now: NOW });
    expect(tick).toMatchObject({ linted: 1, sent: 1, routineFired: 0, templated: 0 });
    expect(world.fires).toEqual([]);
    const record = world.sent.find((s) => s.url.endsWith("createRecord"))!;
    expect(record.body).toMatchObject({ collection: "app.bsky.feed.post", record: { text: `New episode: Stromatolites. ${PIECE.url}` } });
    expect((record.body.record as { facets: unknown[] }).facets).toHaveLength(1);
    expect((await posts())[0]).toMatchObject({ status: "sent", source: "predrafted", createdBy: "Claude 1.0" });
  });

  it("PLANT: a post failing the lint is held, and goes only once edited and approved", async () => {
    const id = await account("germomics-bluesky");
    const world = fakeWorld();
    await draftSocialPost(testEnv.DB, { accountKey: "germomics-bluesky", projectId, itemId: "post-one", text: "Let's delve into the tapestry of the Paluxy.", createdBy: "Claude" });
    await recordPublication(testEnv.DB, projectId, PIECE, NOW);
    await processSocial(env, { fetcher: world.fetch, now: NOW });
    const [held] = await posts();
    expect(held).toMatchObject({ status: "held" });
    expect(JSON.parse(held!.lint)).toEqual(['"delve" is on the AI-habits list.', '"tapestry" is on the AI-habits list.']);
    expect(world.sent).toEqual([]);

    const o = await owner();
    expect(await decidePost(testEnv.DB, o, held!.id, { action: "approve" })).toMatchObject({ ok: false });
    await setSwitches(testEnv.DB, o, id, { mode: "approval" });
    expect(await decidePost(testEnv.DB, o, held!.id, { action: "edit", text: `A new episode on the Paluxy's stromatolites. ${PIECE.url}` })).toMatchObject({ ok: true, findings: [] });
    expect(await decidePost(testEnv.DB, o, held!.id, { action: "approve" })).toEqual({ ok: true });
    expect((await processSocial(env, { fetcher: world.fetch, now: NOW })).sent).toBe(1);
  });
});

describe("the routine, and the template only after it fails", () => {
  async function published() {
    await account("germomics-bluesky");
    await recordPublication(testEnv.DB, projectId, PIECE, NOW);
  }

  it("batches waiting items across accounts into one routine run, after the batch delay", async () => {
    await account("germomics-bluesky");
    await account("foxing-bluesky");
    await recordPublication(testEnv.DB, projectId, PIECE, NOW);
    const world = fakeWorld();
    expect((await processSocial(env, { fetcher: world.fetch, now: NOW })).routineFired).toBe(0); // Still gathering.
    const tick = await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) });
    expect(tick).toMatchObject({ routineFired: 1, templated: 0 });
    expect(world.fires).toHaveLength(1);
    expect(world.fires[0]!.headers).toMatchObject({ authorization: "Bearer sk-ant-oat01-test", "anthropic-version": "2023-06-01" });
    expect(world.fires[0]!.text).toContain("germomics-bluesky");
    expect(world.fires[0]!.text).toContain("foxing-bluesky");
    expect(world.fires[0]!.text).toContain("Dustin's summary: What the river keeps.");
    expect(world.fires[0]!.text).toContain("do not reply to anyone");
  });

  it("uses the routine's draft when it arrives in time, and no template", async () => {
    await published();
    const world = fakeWorld();
    await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) });
    await draftSocialPost(testEnv.DB, { accountKey: "germomics-bluesky", projectId, itemId: "post-one", text: `Stromatolites, and what the river keeps. ${PIECE.url}`, createdBy: "routine" });
    const tick = await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS + 60_000) });
    expect(tick).toMatchObject({ sent: 1, templated: 0 });
    expect((await posts()).map((p) => [p.source, p.status])).toEqual([["routine", "sent"]]);
  });

  it("PLANT: no template while the routine still has time, and the template once it has had its time", async () => {
    await published();
    const world = fakeWorld();
    await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) });
    expect((await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS + ROUTINE_WAIT_MS - 60_000) })).templated).toBe(0);
    expect(await posts()).toEqual([]);
    const tick = await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS + ROUTINE_WAIT_MS + 60_000) });
    expect(tick).toMatchObject({ templated: 1, sent: 1 });
    expect((await posts())[0]).toMatchObject({ source: "template", status: "sent", text: `New: ${PIECE.title}. ${PIECE.summary} ${PIECE.url}` });
  });

  it("PLANT: a routine that refuses the run means the template at once", async () => {
    await published();
    const world = fakeWorld(401);
    const tick = await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) });
    expect(tick.templated).toBe(1);
    expect(tick.errors.join()).toContain("the routine refused the run (401 authentication_error: no)");
  });

  it("PLANT: the hourly limit is not a failure: the item waits, and the next tick tries again", async () => {
    await published();
    let status = 429;
    const world = fakeWorld(() => status);
    expect(await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) })).toMatchObject({ templated: 0, routineFired: 0 });
    status = 200;
    expect(await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS + 15 * 60_000) })).toMatchObject({ routineFired: 1, templated: 0 });
    expect(world.fires).toHaveLength(2);
  });

  it("PLANT: with the routine's daily cap reached, the template", async () => {
    for (const hour of [1, 2, 3]) {
      await testEnv.DB.prepare("INSERT INTO social_routine_runs (kind, requested_at, events, status) VALUES ('batch', ?, '[]', 'fired')")
        .bind(`2026-09-27T0${hour}:00:00.000Z`)
        .run();
    }
    await published();
    const world = fakeWorld();
    const tick = await processSocial(env, { fetcher: world.fetch, now: later(BATCH_DELAY_MS) });
    expect(tick.templated).toBe(1);
    expect(world.fires).toEqual([]);
  });

  it("PLANT: with no routine set up, the template", async () => {
    await published();
    const e = { ...env, SOCIAL_ROUTINE_URL: undefined } as Env;
    expect((await processSocial(e, { fetcher: fakeWorld().fetch, now: later(BATCH_DELAY_MS) })).templated).toBe(1);
  });
});

