// The one view's index: what the site lists, searched with FTS5, filtered, and kept in step with the
// site, within a bounded number of requests per run.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { beforeEach, describe, expect, it } from "vitest";

import {
  ftsQuery,
  MAX_BODY_FETCHES,
  REFRESH_MAX_SUBREQUESTS,
  REFRESH_SUBREQUEST_BUDGET,
  refreshIndex,
  kindsIn,
  searchItems,
  SUBREQUEST_LIMIT,
} from "~/lib/index.server";

import { addProject, resetDb, testEnv } from "./env";
import { connectedEnv, fakeSite } from "./site";

let projectId: number;

beforeEach(async () => {
  await resetDb();
  projectId = await addProject("de-info", "dustinedwards");
});

async function seeded(posts: Record<string, string>, published: string[] = []) {
  const adapter = memoryAdapter();
  for (const [id, source] of Object.entries(posts)) {
    const saved = await adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: "seed" });
    if (published.includes(id)) await adapter.content.publish(id, { expectedVersion: saved.version, changeId: "seed" });
  }
  return fakeSite(adapter);
}

describe("refresh", () => {
  it("indexes every item and finds one by a word in its body, not only its title", async () => {
    const site = await seeded(
      {
        "workers-caching": "---\ntitle: Caching on Workers\n---\nA note on purge tags.\n",
        "fts-notes": "---\ntitle: Search notes\n---\nPorter stemming makes searching find searches.\n",
      },
      ["workers-caching"],
    );
    const result = await refreshIndex(connectedEnv(), { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(result).toEqual({ listed: 2, fetched: 2, removed: 0, pending: 0 });

    const env = connectedEnv();
    expect((await searchItems(env.DB, projectId, { q: "purge" })).map((i) => i.itemId)).toEqual(["workers-caching"]);
    expect((await searchItems(env.DB, projectId, { q: "search" })).map((i) => i.itemId)).toEqual(["fts-notes"]);
    // A prefix while typing. The porter stemmer stores "stemming" as "stem", so "stem" finds it and
    // "stemm" would not: a partial word past the stem misses until the word is complete.
    expect((await searchItems(env.DB, projectId, { q: "stem" })).map((i) => i.itemId)).toEqual(["fts-notes"]);
    expect((await searchItems(env.DB, projectId, { q: "stemming" })).map((i) => i.itemId)).toEqual(["fts-notes"]);
    expect((await searchItems(env.DB, projectId, { status: "published" })).map((i) => i.itemId)).toEqual(["workers-caching"]);
    expect(await searchItems(env.DB, projectId, { q: "nothing-like-this" })).toEqual([]);
  });

  it("keeps a site's data kinds out of the writing lists and their kinds, whatever the kind is called", async () => {
    const db = connectedEnv().DB;
    const row = (itemId: string, kind: string, path: string | null, status = "published") =>
      db
        .prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, path, synced_at) VALUES (?, ?, ?, ?, ?, ?, '2026-10-07T00:00:00Z')")
        .bind(projectId, itemId, kind, itemId, status, path);
    await db.batch([
      row("a-post", "post", "/writing/a-post"),
      row("a-draft", "post", null, "draft"),
      row("page.about", "page", "/about"),
      row("phage.acorn15", "phage", "/research/phages#acorn15"),
      row("roster.2017", "roster", "/teaching/phage-discovery#year-2017"),
      row("essay.first", "a-kind-only-in-draft", null, "draft"),
      row("equipment.heat-block", "equipment", null),
      row("reagent.agar", "reagent", null),
      row("widget.x", "some-kind-no-one-listed", null),
    ]);
    const listed = await searchItems(db, projectId, {});
    expect(listed.map((i) => i.itemId).sort()).toEqual(["a-draft", "a-post", "essay.first", "page.about", "phage.acorn15", "roster.2017"]);
    expect(await searchItems(db, projectId, { kind: "equipment" })).toEqual([]);
    expect((await searchItems(db, projectId, { kind: "phage" })).map((i) => i.itemId)).toEqual(["phage.acorn15"]);
    expect(await kindsIn(db, projectId)).toEqual(["a-kind-only-in-draft", "page", "phage", "post", "roster"]);
  });

  it("reads a body again only when the item changed, and drops an item the site no longer lists", async () => {
    const site = await seeded({ a: "# A\n", b: "# B\n" });
    const env = connectedEnv();
    await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);

    const again = await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(again.fetched).toBe(0);

    const current = site.adapter.store.get("a")!.doc.version;
    await site.adapter.content.saveDraft("a", { source: "# A\nnew words\n", expectedVersion: current, changeId: "x" });
    site.adapter.store.delete("b");
    const third = await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(third).toMatchObject({ listed: 1, fetched: 1, removed: 1 });
    expect((await searchItems(env.DB, projectId, { q: "new words" })).map((i) => i.itemId)).toEqual(["a"]);
    expect(await searchItems(env.DB, projectId, { q: "B" })).toEqual([]);
  });

  it("reads at most MAX_BODY_FETCHES bodies per run and reports the rest as pending", async () => {
    const posts = Object.fromEntries(Array.from({ length: MAX_BODY_FETCHES + 5 }, (_, i) => [`p${String(i).padStart(2, "0")}`, `# P${i}\n`]));
    const site = await seeded(posts);
    const env = connectedEnv();
    const first = await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(first).toMatchObject({ fetched: MAX_BODY_FETCHES, pending: 5 });
    expect(site.requests.filter((r) => r.startsWith("GET /api/carrel/v1/content/")).length).toBe(MAX_BODY_FETCHES);
    const second = await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(second).toMatchObject({ fetched: 5, pending: 0 });
  });
});

/**
 * D1 with every call counted, as the platform counts subrequests: each statement run and each batch
 * is one. Statements are unwrapped before a batch, which D1 insists on.
 */
function countingD1(db: D1Database) {
  let calls = 0;
  const real = new WeakMap<object, D1PreparedStatement>();
  const wrap = (stmt: D1PreparedStatement): D1PreparedStatement => {
    const proxy = new Proxy(stmt, {
      get(target, prop) {
        if (prop === "bind") return (...args: unknown[]) => wrap(target.bind(...args));
        if (prop === "first" || prop === "run" || prop === "all" || prop === "raw") {
          return (...args: unknown[]) => {
            calls++;
            return (target[prop] as (...a: unknown[]) => unknown).apply(target, args);
          };
        }
        const value = Reflect.get(target, prop, target);
        return typeof value === "function" ? value.bind(target) : value;
      },
    });
    real.set(proxy, stmt);
    return proxy;
  };
  const counted = new Proxy(db, {
    get(target, prop) {
      if (prop === "prepare") return (query: string) => wrap(target.prepare(query));
      if (prop === "batch") {
        return (stmts: D1PreparedStatement[]) => {
          calls++;
          return target.batch(stmts.map((s) => real.get(s) ?? s));
        };
      }
      if (prop === "exec") {
        return (query: string) => {
          calls++;
          return target.exec(query);
        };
      }
      const value = Reflect.get(target, prop, target);
      return typeof value === "function" ? value.bind(target) : value;
    },
  });
  return { db: counted, calls: () => calls };
}

describe("the refresh's subrequests (Workers Paid)", () => {
  it("keeps the cap's worst case inside its budget, and the budget a tenth of the plan's limit", () => {
    expect(SUBREQUEST_LIMIT).toBe(10_000);
    expect(REFRESH_SUBREQUEST_BUDGET).toBe(1_000);
    expect(REFRESH_MAX_SUBREQUESTS).toBe(412);
    expect(REFRESH_MAX_SUBREQUESTS).toBeLessThanOrEqual(REFRESH_SUBREQUEST_BUDGET);
  });

  it("stays under the limit when every post needs its body read: counted, not assumed", async () => {
    const posts = Object.fromEntries(Array.from({ length: MAX_BODY_FETCHES + 50 }, (_, i) => [`p${String(i).padStart(3, "0")}`, `# P${i}
`]));
    const site = await seeded(posts);
    const counting = countingD1(testEnv.DB);
    const env = connectedEnv({ DB: counting.db });
    const before = site.requests.length;

    const result = await refreshIndex(env, { id: projectId, site: "dustinedwards" }, site.fetch);
    expect(result).toMatchObject({ listed: MAX_BODY_FETCHES + 50, fetched: MAX_BODY_FETCHES, pending: 50 });

    const fetches = site.requests.length - before;
    const used = fetches + counting.calls();
    // Two list pages, one read per body; two D1 calls up front and one batch per body.
    expect(fetches).toBe(2 + MAX_BODY_FETCHES);
    expect(counting.calls()).toBe(2 + MAX_BODY_FETCHES);
    expect(used).toBeLessThanOrEqual(REFRESH_MAX_SUBREQUESTS);
    expect(used).toBeLessThan(SUBREQUEST_LIMIT);
  });
});

describe("the search expression", () => {
  it("treats punctuation as text, never FTS5 syntax", () => {
    expect(ftsQuery('title:"x" OR NEAR(a b)')).toBe('"title" "x" "OR" "NEAR" "a" "b"*');
    expect(ftsQuery("---")).toBeNull();
  });

  it("returns nothing for a query with no words rather than everything", async () => {
    const env = connectedEnv();
    expect(await searchItems(env.DB, projectId, { q: "***" })).toEqual([]);
  });
});

test/kinds.test.ts.source:
// Every kind the site reports, end to end through the routes: a non-post kind lists under its own
// kind and filter, opens, saves, previews, publishes and shows its revisions exactly as a post does,
// and a data kind the site will not write stays out of the lists and, if reached, shows the site's
// own refusal. Carrel has no per-kind code; the kinds and paths come from the site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { loader as historyLoader } from "~/routes/history";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb } from "./env";
import { connectedEnv, fakeSite, kindedAdapter, viewerFor } from "./site";

const SLUG = "de-info";
const OWNER = "owner@test.invalid";
let projectId = 0;

beforeEach(async () => {
  await resetDb();
  await addPerson(OWNER, { owner: true });
  projectId = await addProject(SLUG, "dustinedwards");
});

async function contextFor(env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(OWNER));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settled<T>(run: () => Promise<T>): Promise<T | Response> {
  try {
    return await run();
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function seeded() {
  const site = fakeSite(kindedAdapter());
  vi.stubGlobal("fetch", site.fetch);
  const env = connectedEnv();
  const put = async (id: string, source: string, publish: boolean) => {
    const saved = await site.adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: `seed-${id}` });
    if (publish) await site.adapter.content.publish(id, { expectedVersion: saved.version, changeId: `seed-pub-${id}` });
  };
  await put("a-post", "---\ntitle: A post\n---\nWords.\n", true);
  await put("draft-post", "---\ntitle: A draft post\n---\nNot yet.\n", false);
  await put("phage.acorn15", "---\ntitle: Acorn15\nhost: Gordonia\n---\nA cluster DJ phage.\n", true);
  await put("roster.2017", "---\ntitle: 2017 cohort\nyear: 2017\n---\n", true);
  await put("procedure.coi-primers", "---\ntitle: COI primers\n---\nThe PCR protocol.\n", true);
  await refreshIndex(env, { id: projectId, site: "dustinedwards" });
  return { site, env };
}

const form = (fields: Record<string, string>) => {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
};

describe("every kind the site reports", () => {
  it("lists each writing kind under its own kind, and the kind filter narrows to it", async () => {
    const { env } = await seeded();
    const context = await contextFor(env);
    const all = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(all.kinds).toEqual(["phage", "post", "procedure", "roster"]);
    const byId = Object.fromEntries(all.items.map((i) => [i.itemId, i]));
    expect(byId["phage.acorn15"]).toMatchObject({ kind: "phage", path: "/research/phages#acorn15", status: "published" });
    expect(byId["roster.2017"]).toMatchObject({ kind: "roster", path: "/teaching/phage-discovery#year-2017" });
    expect(byId["procedure.coi-primers"]).toMatchObject({ kind: "procedure", path: "/research/protocols/coi-primers" });
    expect(byId["draft-post"]).toMatchObject({ kind: "post", status: "draft", path: null });

    const phages = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}?kind=phage`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(phages.items.map((i) => i.itemId)).toEqual(["phage.acorn15"]);
  });

  it("opens, saves, previews, publishes and shows the history of a non-post kind", async () => {
    const { env, site } = await seeded();
    const id = "phage.acorn15";
    const params = { project: SLUG, item: id };
    const url = `https://carrel.test/p/${SLUG}/e/${id}`;

    const opened = (await editorLoader({ request: new Request(url), params, context: await contextFor(env) } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(opened.title).toBe("Acorn15");
    expect(opened.path).toBe("/research/phages#acorn15");
    // Links written in the editor go to each item's own address on the site, a draft post to where the site's posts live.
    expect(opened.linkTargets.map((t) => t.href).sort()).toEqual([
      "/research/protocols/coi-primers",
      "/teaching/phage-discovery#year-2017",
      "/writing/a-post",
      "/writing/draft-post",
    ]);

    const source = "---\ntitle: Acorn15\nhost: Gordonia terrae\n---\nA cluster DJ phage, found in 2015.\n";
    const saved = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "save", source, expectedVersion: opened.version! }) }), params, context: await contextFor(env) } as never);
    expect(saved).toMatchObject({ intent: "write", outcome: { ok: true, action: "save", status: "published" } });
    const version = (saved as { outcome: { version: string } }).outcome.version;

    const previewed = (await settled(async () => previewLoader({ request: new Request(`${url}/preview`), params, context: await contextFor(env) } as never))) as Response;
    expect(previewed.status).toBe(200);
    expect(await previewed.text()).toContain("found in 2015");

    const published = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "publish", source, expectedVersion: version }) }), params, context: await contextFor(env) } as never);
    expect(published).toMatchObject({ intent: "write", outcome: { ok: true, action: "publish", status: "published" } });
    expect((await site.adapter.content.get(id))?.source).toContain("found in 2015");

    const history = (await historyLoader({ request: new Request(`${url}/history`), params, context: await contextFor(env) } as never)) as { revisions: unknown[] | null };
    expect(history.revisions?.length).toBe(4);
  });

  it("keeps a data kind out of the lists, and shows the site's own refusal if one is written", async () => {
    const { env, site } = await seeded();
    // The site's import puts registry rows in place directly; Carrel never wrote them.
    await env.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, 'equipment.heat-block', 'equipment', 'Heat block', 'published', '2026-10-10T00:00:00Z')").bind(projectId).run();
    const context = await contextFor(env);
    const listed = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(listed.kinds).not.toContain("equipment");
    expect(listed.items.map((i) => i.itemId)).not.toContain("equipment.heat-block");

    const params = { project: SLUG, item: "equipment.heat-block" };
    const written = await editorAction({
      request: new Request(`https://carrel.test/p/${SLUG}/e/equipment.heat-block`, { method: "POST", body: form({ intent: "save", source: "---\nname: Heat block\n---\n", expectedVersion: "" }) }),
      params,
      context: await contextFor(env),
    } as never);
    expect(written).toMatchObject({ intent: "write", outcome: { ok: false, reason: "refused", message: "The site's equipment entries are edited in the site's repository, not through Carrel." } });
    expect(await site.adapter.content.get("equipment.heat-block")).toBeNull();
  });
});

test/google-routes.test.ts.source:
// The Google routes through their loaders: manuscripts and Connect Google are the Owner's, and the
// OAuth round trip runs through the real route with the fake Google behind it.

import { RouterContextProvider } from "react-router";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { clearSaTokenCache } from "~/lib/google/service-account.server";
import { loader as authLoader } from "~/routes/auth.google";
import { loader as homeLoader } from "~/routes/home";
import { loader as manuscriptsLoader } from "~/routes/manuscripts";

import { addPerson, resetDb, testEnv } from "./env";
import { CODE, fakeGoogle, serviceAccountKey } from "./google";
import { viewerFor } from "./site";

let key: Awaited<ReturnType<typeof serviceAccountKey>>;
beforeAll(async () => {
  key = await serviceAccountKey();
});

let env: Env;
beforeEach(async () => {
  clearSaTokenCache();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("editor@test.invalid");
  vi.stubGlobal("fetch", fakeGoogle({ publicJwk: key.publicJwk }).fetch);
  env = {
    ...testEnv,
    GOOGLE_SA_KEY: key.json,
    GOOGLE_OAUTH_CLIENT_ID: "id",
    GOOGLE_OAUTH_CLIENT_SECRET: "secret",
    GOOGLE_TOKEN_KEY: btoa(String.fromCharCode(...new Uint8Array(32).fill(7))),
    GOOGLE_MANUSCRIPTS_FOLDER_ID: "folderRoot1",
  } as Env;
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

describe("Google routes", () => {
  it("PLANT: manuscripts and Connect Google are 404 to anyone but the Owner", async () => {
    const req = new Request("https://carrel.test/manuscripts");
    expect(((await settle(manuscriptsLoader({ request: req, params: {}, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const start = new Request("https://carrel.test/auth/google/start");
    expect(((await settle(authLoader({ request: start, params: { step: "start" }, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toBeNull();
  });

  it("connects Google through the real routes and says so on the home page", async () => {
    const owner = await context("owner@test.invalid");
    const start = (await authLoader({ request: new Request("https://carrel.test/auth/google/start"), params: { step: "start" }, context: owner } as never)) as Response;
    const google = new URL(start.headers.get("Location")!);
    expect(google.hostname).toBe("accounts.google.com");
    const back = new Request(`https://carrel.test/auth/google/callback?state=${google.searchParams.get("state")}&code=${encodeURIComponent(CODE)}`);
    const done = (await authLoader({ request: back, params: { step: "callback" }, context: await context("owner@test.invalid") } as never)) as Response;
    const message = new URL(done.headers.get("Location")!, "https://carrel.test").searchParams.get("google");
    expect(message).toBe("Google is connected for Send to Docs and Import (drive.file only).");
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toEqual({ configured: true, connected: true });
  });

  it("shows the manuscripts page with the setup still missing, rather than failing", async () => {
    env = { ...env, GOOGLE_SA_KEY: undefined } as Env;
    const data = (await manuscriptsLoader({ request: new Request("https://carrel.test/manuscripts?q=x"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof manuscriptsLoader>
    >;
    expect(data.setup).toMatch(/^GOOGLE_SA_KEY is not set/);
    expect(data.files).toEqual([]);
  });
});

test/social-route.test.ts.source:
// The social page through its loader and action: the Owner's alone, and an account added there
// starts off, in approval mode.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { action as socialAction, loader as socialLoader } from "~/routes/social";

import { addPerson, addProject, resetDb, testEnv } from "./env";
import { viewerFor } from "./site";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("editor@test.invalid");
  await addProject("germomics", "dustinedwards");
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env: testEnv, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

describe("the social page", () => {
  it("PLANT: is 404 to anyone but the Owner", async () => {
    await expect(socialLoader({ request: new Request("https://carrel.test/social"), params: {}, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });

  it("adds an account that starts off, in approval mode, and says the routine is not set up", async () => {
    const body = new FormData();
    for (const [k, v] of Object.entries({ intent: "add-account", key: "germomics-bluesky", name: "Germomics", platform: "bluesky", kind: "brand", handle: "@germomics.bsky.social" })) body.set(k, v);
    expect(await socialAction({ request: new Request("https://carrel.test/social", { method: "POST", body }), params: {}, context: await context("owner@test.invalid") } as never)).toEqual({ ok: true });
    const data = (await socialLoader({ request: new Request("https://carrel.test/social"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof socialLoader>>;
    expect(data.accounts).toMatchObject([{ key: "germomics-bluesky", handle: "germomics.bsky.social", enabled: false, mode: "approval" }]);
    expect(data.routine).toBe("SOCIAL_ROUTINE_URL and SOCIAL_ROUTINE_TOKEN are not both set.");
  });
});
